var clickedScrollPos = 0;
var discJustClicked = false;
var selectedDisc;
var disContBackTemp = $("<div class='disc-back-to-content'><a href='#' onclick='backToContent();return false;' style='color:blue'>Back to Previous Section</a></div>");

$("sup a").on('click', function() {
    $(this).addClass('clicked');
})

function disclaimerJump(locat) {
    $(locat).addClass("clicked");
    openDisclaimerAccordian()
    clickedScrollPos = $(window).scrollTop();
    setBackToContentLocation(locat)
    discJustClicked = true;
    return false;
}

function backToContent() {
    let loc = window.location.hash;
    $('html, body').animate({
        scrollTop: clickedScrollPos + 'px'
    }, 1500, function() {
        $("sup a.clicked[href='" + loc + "']").focus();
        $("sup a.clicked[href='" + loc + "']").css('text-decoration', 'underline');
    });
    setTimeout(() => {
        $("sup a.clicked[href='" + loc + "']").removeClass('clicked');
        history.pushState('', '', window.location.pathname + window.location.search);
    }, 1600);

}


function setBackToContentLocation(btc) {
    var discP = btc.hash.substr(1);
    $('html, body').animate({
        scrollTop: $("#" + discP).offset().top - 50 + 'px'
    }, 1500, function() {
        window.location.hash = discP;
        $(".disc-back-to-content").show();
        let loc = window.location.hash
        $(".disc-back-to-content a").focus();
    });



    selectedDisc = $("#" + discP + "-content")
    disContBackTemp.find('a').attr('aria-describedby', discP + '-content')
    $("#" + discP + "-content").append(disContBackTemp)
    $(".disc-back-to-content").show()
    $("#" + discP + "-content").addClass("disc-selected")

}

function openDisclaimerAccordian() {
    var discButton = $("#footer-section-disclosure").find(":button")
    if ($(discButton).hasClass("collapsed")) {
        discButton.click()
    }
}

window.addEventListener("load", addDiscLinks);

function addDiscLinks() {
    $('a[name="disclaimer-sup"]').each(function() {
        // Skip if aria-label already provides the accessible name (set by promo_dynamic_disclaimer.js)
        if ($(this).attr('aria-label')) return;
        var listElem = document.createElement('span');
        listElem.className = 'sr-only';
        listElem.textContent = "footnote";
        $(this).prepend(listElem);
    });
    $('a[name="disclaimer-sup"]').on('click', function(e) {
        e.stopPropagation();
        e.stopImmediatePropagation();
        e.preventDefault();
        disclaimerJump(this);
    });
}

window.addEventListener("scroll", checkBTCscreen);

function checkBTCscreen() {
    if ($('.disc-back-to-content').length) {
        var isElementInView = Utils1.isElementInView($('.disc-back-to-content'), false);
        if (isElementInView) {
            discJustClicked = false;
        } else {
            if (!discJustClicked) {
                $(".disc-back-to-content").hide()
                $(selectedDisc).removeClass("disc-selected")
            }
        }
    }
}

function isScrolledIntoView(elem) {
    var docViewTop = $(window).scrollTop();
    var docViewBottom = docViewTop + $(window).height();

    var elemTop = $(elem).offset().top;
    var elemBottom = elemTop + $(elem).height();

    return ((elemBottom <= docViewBottom) && (elemTop >= docViewTop));
}

function Utils() {

}

Utils.prototype = {
    constructor: Utils,
    isElementInView: function(element, fullyInView) {
        var pageTop = $(window).scrollTop();
        var pageBottom = pageTop + $(window).height();
        var elementTop = $(element).offset().top;
        var elementBottom = elementTop + $(element).height();

        if (fullyInView === true) {
            return ((pageTop < elementTop) && (pageBottom > elementBottom));
        } else {
            return ((elementTop <= pageBottom) && (elementBottom >= pageTop));
        }
    }
};

var Utils1 = new Utils();

setTimeout(() => {
    $(function() {
        $("[data-handle='playPauseNotifier']").css('display', 'none');
        $("[data-handle='backgroundFocus']").css('display', 'none');

        $("#recaptcha-form .grecaptcha-logo>iframe").removeAttr("role");

    });
}, 5000);

///////////////////////////
// HELPER: Fetch API wrapped with a timeout
// SOURCE: https://lowmess.com/blog/fetch-with-timeout
//////////////////////////
const fetchWithTimeout = (uri, options = {}, time = 10000) => {
    // Set up our `AbortController`, and create a request options object
    // that includes the controller's `signal` to pass to `fetch`.
    const controller = new AbortController();
    const config = { ...options,
        signal: controller.signal
    };

    // Set a timeout limit for the request using `setTimeout`. If the body
    // of this timeout is reached before the request is completed, it will
    // be cancelled.
    const timeout = setTimeout(() => {
        controller.abort();
    }, time);

    return fetch(uri, config)
        .then((response) => {
            // Because _any_ response is considered a success to `fetch`, we
            // need to manually check that the response is in the 200 range.
            if (!response.ok) {
                throw new Error(`${response.status}: ${response.statusText}`);
            }

            return response;
        })
        .catch((error) => {
            // When we abort our `fetch`, the controller conveniently throws
            // a named error, allowing us to handle them separately from
            // other errors.
            if (error.name === "AbortError") {
                throw new Error("Response timed out");
            }

            throw new Error(error.message);
        });
};


