$(function() {
    $('.js-form-group input').on("mouseover focus", function() {
        $(this).parents('.form-group').addClass('focused');
    });

    $('.js-form-group input').on("mouseout blur", function() {
        var inputValue = $(this).val();
        if (inputValue == "") {
            $(this).parents('.form-group').removeClass('focused');
        }
    })

    $('.footer .screen_reader_blank').remove();

    onResize = function() {
        if ($(window).width() <= 991) {
            $('.footer__section .accordion__header').each(function() {
                if ($(this).hasClass("is-expanded")) {
                    $(this).attr("aria-expanded", true);
                } else {
                    $(this).attr("aria-expanded", false);
                }
            });

            $('.js-tru-accordion__trigger').each(function() {
                $(this).attr("role", "button");
                $(this).attr("tabindex", "0");
                if ($(this).hasClass("is-expanded")) {
                    $(this).next().css("display", "block");
                } else {
                    $(this).next().css("display", "none");
                }
            });
        }

        if ($(window).width() > 992) {
            $('.footer__section .js-tru-accordion__target').css('display', 'block');
            $('.footer__section .js-tru-accordion__trigger').removeAttr("aria-expanded");
            $('.footer__section .js-tru-accordion__trigger').removeAttr("role");
            $('.footer__section .js-tru-accordion__trigger').removeAttr("tabindex");
        }
    }

    $(document).ready(onResize);
    $(window).resize(onResize);

});
