window.addEventListener("load", makeSticky);

function makeSticky() {
    if ($(".vertical-desktop")[0]) {
        var $window = $(window),
            $stickyElement = $('.vertical-desktop'),
            elTop = $stickyElement.offset().top;
        $window.scroll(function() {
            $stickyElement.toggleClass('sticky-social', $window.scrollTop() > elTop);
        })
        var resourcesSection = $('.footertag'),
            resourcesTop = resourcesSection.offset().top;
        $window.scroll(function() {
            $stickyElement.toggleClass('sticky-hide', $window.scrollTop() > resourcesTop - 220);
        });
    }
}
