function positionCustomCard() {
    /* Added for custom card positioning */
    var $articleBlock = $('.Dynamic-Card-component-instance.relResources .articleCardSec');
    var $artCards = $articleBlock.children('.card');
    var $artCustomCard = $artCards.filter('.ret2Movmnt');
    var artCardPos = $('.Dynamic-Card-component-instance.relResources').data('position');

    if ($artCards.length === 3 && $artCustomCard.length === 1) {
        if (artCardPos === 'left') {
            $artCustomCard.detach().insertBefore($artCards.eq(0));
        } else if (artCardPos === 'middle') {
            $artCustomCard.detach().insertAfter($artCards.eq(0));
        }
    }
}

