///////////////////////////////////////////////////
///////////////////////////////////////////////////
// Set active page
///////////////////////////////////////////////////
///////////////////////////////////////////////////
// get all page link items to set the active state
//window.addEventListener('DOMContentLoaded',function(){
let pageLinkButtons = document.getElementsByClassName("navbar-secondary__link-item");
// get the menu toggle button to set the name at mobile
let toggleButton = document.getElementById("toggle-button");
let toggleButtonText = document.getElementById("toggle-button-text")
let testingForActivePageSecondaryNav = false
// loop through the buttons and add the active class to the button for the current page
if (toggleButton) {
    if (pageLinkButtons.length > 1) {
        for (let i = 0; i < pageLinkButtons.length; i++) {
            let pageLink = pageLinkButtons[i].getAttribute("href")
            if (window.location.pathname === pageLink) {
                pageLinkButtons[i].parentElement.classList.add("active");
                pageLinkButtons[i].parentElement.setAttribute("aria-current", "page");
                toggleButtonText.innerHTML = pageLinkButtons[i].innerText;
                testingForActivePageSecondaryNav = true
            }
        }
    }

    // setting backup menu text if no active page is found
    if (!testingForActivePageSecondaryNav) {
        toggleButtonText.innerHTML = "Menu";
    }
}

///////////////////////////////////////////////////
///////////////////////////////////////////////////
// Sticky Header
///////////////////////////////////////////////////
///////////////////////////////////////////////////
// get elements that will have classes added or removed
let secondaryNavbar = document.querySelector(".navbar-secondary__wrapper");
let mainHeader = document.querySelector("header");
let secondaryNavbarMobile = document.querySelector(".navbar-secondary__wrapper.display--mobile");
let secondaryNavbarCtaMobileButtonExperienceFragment = document.querySelector('.navbar-secondary__wrapper.display--mobile .navbar-secondary__cta-button-container div')
let secondaryNavbarCtaButton = document.querySelector(".navbar-secondary__cta-button-container");
let secondaryNavbarCtaButtonExperienceFragment = document.querySelector(".navbar-secondary__cta-button-container div");
if ((secondaryNavbar !== null || undefined) && (mainHeader !== null || undefined)) {
    let secondaryNavbarCtaButtonSticky = "false";
    if ((secondaryNavbarCtaButton !== null || undefined) && (secondaryNavbarCtaButton.hasAttribute("data-sticky-button"))) {
        secondaryNavbarCtaButtonSticky = secondaryNavbarCtaButton.getAttribute("data-sticky-button");
    }

    let mobilePhoneNumberContainer = document.querySelector(".navbar-secondary__wrapper.display--mobile > .navbar-secondary__container > .navbar-secondary__cta-wrapper > .navbar-secondary__cta-phone-container")
    let mobilePhoneNumberContainerLength
    if (mobilePhoneNumberContainer !== null) {
        mobilePhoneNumberContainerLength = mobilePhoneNumberContainer.innerText.trim().length
    }

    let mobileCtaContainer = document.querySelector(".navbar-secondary__wrapper.display--mobile > .navbar-secondary__container > .navbar-secondary__cta-wrapper")
    if (mobilePhoneNumberContainerLength === 0 && mobilePhoneNumberContainer !== null) {
        mobileCtaContainer.classList.add("reset-secondary-navbar")
    }

    if (mobileCtaContainer.childElementCount === 0) {
        mobileCtaContainer.classList.add("secondary-navbar--no-cta-present")
    }

    // configuration for the observer
    const secondarynavconfig = {
        root: null,
        threshold: [0, 0.1]
    };
    // create the observer
    let navObserver = new IntersectionObserver(function(entry) {
        addSecondaryNavBarClasses(entry[0].isIntersecting)
    }, secondarynavconfig);
    // observe the navbar
    navObserver.observe(mainHeader);

    function addSecondaryNavBarClasses(intersectionStatus) {
        // makes the secondary nav sticky if a user scrolls down far enough on the page
        const secondaryNavbarId = secondaryNavbar.parentElement.getAttribute("id");
        if (secondaryNavbarId.includes("-0")) {
            var secondaryNavbarId2 = secondaryNavbarId.slice(0, secondaryNavbarId.lastIndexOf('-'));
            var secondaryNavbarPlaceholder = document.querySelector("#" + secondaryNavbarId2 + "--placeholder");
        } else {
            var secondaryNavbarPlaceholder = document.querySelector("#" + secondaryNavbarId + "--placeholder");
            var secondaryNavbarHeight = document.querySelector(`#${secondaryNavbarId}`).offsetHeight;
        }
        // hides the cta button until the nav is sticky, if defined by the author
        if ((secondaryNavbarCtaButton !== null || undefined) && secondaryNavbarCtaButtonSticky === "true") {
            if (intersectionStatus === false) {
                secondaryNavbarCtaButtonExperienceFragment.classList.remove("hidden-cta");
                secondaryNavbarCtaMobileButtonExperienceFragment.classList.remove("hidden-cta");
            } else {
                secondaryNavbarCtaButtonExperienceFragment.classList.add("hidden-cta")
                secondaryNavbarCtaMobileButtonExperienceFragment.classList.add("hidden-cta");
            }
        }
    }
}

///////////////////////////////////////////////////
///////////////////////////////////////////////////
// Toggle Dropdown
///////////////////////////////////////////////////
///////////////////////////////////////////////////
function navToggle() {
    let dropdownMenu = document.getElementById("dropdown-menu");
    let toggleButton = document.getElementById("toggle-button");
    if (dropdownMenu.style.display === "none") {
        dropdownMenu.style.display = "flex";
        toggleButton.setAttribute('aria-expanded', true);
    } else {
        dropdownMenu.style.display = "none";
        toggleButton.setAttribute('aria-expanded', false);
    }
}

function hideMenu() {
    let dropdown = document.getElementById("dropdown-menu");
    dropdown.style.display = "none";
}
let toggleButtonMobileSecondaryNav = document.getElementById("toggle-button")
if (toggleButtonMobileSecondaryNav !== null || undefined) {
    toggleButtonMobileSecondaryNav.addEventListener("click", function() {
        navToggle()
    });


}
$("#dropdown-menu li").hover(function() {
    $(this).toggleClass('dropLiHover');
});

$(document).mouseup(function(e) {
    let secondaryNavBarDropdownMenu = document.getElementById("dropdown-menu");
    let secondaryNavbarToggleButton = $("#toggle-button");
    if (secondaryNavBarDropdownMenu !== null || undefined) {
        if (!secondaryNavbarToggleButton.is(e.target) &&
            secondaryNavBarDropdownMenu.style.display === "flex" &&
            secondaryNavbarToggleButton.has(e.target).length === 0
        ) {
            navToggle();
        }
    }
});


$(document).ready(function() {
    //cta unique ids function
    let mobileSecondaryNavCtaContainerItems = document.querySelectorAll(".navbar-secondary__wrapper.display--mobile .navbar-secondary__cta-wrapper *")
    mobileSecondaryNavCtaContainerItems.forEach((mobileSecondaryNavCtaContainerItem) => {
        let secondaryNavContainerID = mobileSecondaryNavCtaContainerItem.getAttribute("id")
        if (secondaryNavContainerID) {
            mobileSecondaryNavCtaContainerItem.setAttribute("id", `${secondaryNavContainerID}--secondary-nav-mobile`)
        }
    });
    // observes the footer to push up the button when it hits the bottom of the page
    const mobileSecondaryNavContainer = document.querySelector(".navbar-secondary__wrapper.display--mobile")
    if (mobileSecondaryNavContainer) {
        function updateSecondaryNavFloatingCTA(intersectionBoolean) {
            const truLiveChatFloatingButtonContainer = document.querySelector('.tru-floating--bottom-right')
            const floatingMobileCTA = document.querySelector(".navbar-secondary__wrapper.display--mobile .navbar-secondary__cta-button-container")
            if (!floatingMobileCTA) return
            if (intersectionBoolean) {
                floatingMobileCTA.classList.add("secondary-navbar--floating-cta--bottom-of-page")
                truLiveChatFloatingButtonContainer.classList.add("secondary-navbar--page-bottom")
            }
            if (!intersectionBoolean) {
                floatingMobileCTA.classList.remove("secondary-navbar--floating-cta--bottom-of-page")
                truLiveChatFloatingButtonContainer.classList.remove("secondary-navbar--page-bottom")
            }
        }

        const footerObserverConfig = {
            root: null
        };

        let footerNavObserver = new IntersectionObserver(function(entry) {
            updateSecondaryNavFloatingCTA(entry[0].isIntersecting)
        }, footerObserverConfig);

        const footerLegalDisclosuresNav = document.querySelector(".footer-highlight")
        if (footerLegalDisclosuresNav) footerNavObserver.observe(footerLegalDisclosuresNav);
    }
})
'use strict';

window.GlobalNavigation = function() {
    const qsa = (sel, ctx) => Array.prototype.slice.call((ctx || document).querySelectorAll(sel));
    const qs = (sel, ctx) => (ctx || document).querySelector(sel);
    const getBS5 = () => window.__bootstrap5__;

    const SEL = {
        root: '.global-nav',
        navLinks: '.navbar-top a.nav-link, .navbar-top a.main-nav-toggle, .navbar-top a.nav-links, .navbar-top a.user-locale.nav-link, .navbar-top a.nav-link.dropdown-toggle',
        openAcctToggle: '.user-account .open-act-link > button',
        toggler: '.navbar-toggler',
        navbarBottom: '.navbar .navbar-bottom',
        bottomContainer: '.navbar-bottom .navbar-container',
        overlay: '.truist-signin-overlay',
        signInMobile: '#signOnCompMobile',
        signInDesktop: '#signOnCompDesktop',
        signInClose: '.truist-signon-close-button',
        openActMobile: '#open-act-mobile',
        heroLogin: '.hero-login-component .hero--login-menu--row .login-component',
        moreLink: '#utilMoreDropDown'
    };

    function toggleAriaExpanded(el) {
        el.setAttribute('aria-expanded', el.getAttribute('aria-expanded') === 'false' ? 'true' : 'false');
    }

    function nextFind(el, sel) {
        return el && el.nextElementSibling ? qs(sel, el.nextElementSibling) : null;
    }

    function clearChildren(el) {
        if (el) el.replaceChildren();
    }

    function moveChildren(from, to) {
        if (!from || !to) return;
        while (from.firstChild) to.appendChild(from.firstChild);
    }

    let root;

    function initAriaCurrent() {
        const currentPath = window.location.pathname;
        const navLinks = () => qsa(SEL.navLinks);

        let bestMatch = null;
        let bestMatchLength = 0;
        navLinks().forEach(function(el) {
            const href = el.getAttribute('href');
            if (!href || href === '#') return;
            const linkPath = new URL(href, window.location.origin).pathname;
            if ((currentPath === linkPath || (linkPath !== '/' && currentPath.startsWith(linkPath + '/'))) &&
                (!bestMatch || linkPath.length > bestMatchLength)) {
                bestMatch = el;
                bestMatchLength = linkPath.length;
            }
        });
        if (bestMatch) bestMatch.setAttribute('aria-current', 'page');

        navLinks().forEach(function(el) {
            if (el.classList.contains('dropdown-toggle') && el.getAttribute('aria-expanded') === 'true') {
                setCurrent(el, navLinks());
            }
        });

        const moreLink = qs(SEL.moreLink);
        if (moreLink && moreLink.getAttribute('aria-expanded') === 'true') {
            moreLink.setAttribute('aria-current', 'page');
        }

        const setAcctButtonHrefCurrent = function() {
            const toggleButton = qs(SEL.openAcctToggle);
            if (!toggleButton) return;
            const prefix = '/open-account';
            if (currentPath === prefix || currentPath.startsWith(prefix + '/')) {
                navLinks().forEach(function(el) {
                    el.removeAttribute('aria-current');
                });
                toggleButton.setAttribute('aria-current', 'page');
            }
        };
        setAcctButtonHrefCurrent();

        root.addEventListener('click', function(e) {
            const dd = e.target.closest('.navbar-top a.nav-link.dropdown-toggle');
            if (dd && dd.getAttribute('aria-expanded') === 'true') setCurrent(dd, navLinks());

            const acct = e.target.closest(SEL.openAcctToggle);
            if (acct) setCurrent(acct, navLinks());
        });


    }

    function setCurrent(el, allLinks) {
        (allLinks || qsa(SEL.navLinks)).forEach(function(o) {
            if (o !== el) o.removeAttribute('aria-current');
        });
        el.setAttribute('aria-current', 'page');
    }

    let trapFocusables = null;
    let trapFirst = null;
    let trapLast = null;

    let activeOverlayRefs = null;

    function closeSignInOverlay() {
        const overlay = qs(SEL.overlay, root);
        if (overlay) overlay.classList.remove('is-activate');
        document.body.classList.remove('is-activate');
        disableTabTrap();
        if (activeOverlayRefs && activeOverlayRefs.signInReturnFocus) {
            activeOverlayRefs.signInReturnFocus.focus();
            activeOverlayRefs.signInReturnFocus = null;
        }
    }

    function resolveTrapScope() {
        let scope = SEL.root;
        const signOnMobile = qs(SEL.signInMobile);
        if (signOnMobile) {
            let sib = signOnMobile.nextElementSibling;
            while (sib && !sib.classList.contains('truist-signin-overlay')) sib = sib.nextElementSibling;
            if (sib && sib.classList.contains('is-activate')) scope = SEL.overlay;
        }
        return qs(scope);
    }

    function refreshTrapFocusables() {
        const container = resolveTrapScope();
        if (!container) {
            trapFocusables = trapFirst = trapLast = null;
            return;
        }
        trapFocusables = qsa("input,button,select,textarea,a,[tabindex]:not([tabindex='-1'])", container)
            .filter(function(el) {
                return el.offsetWidth !== 0 || el.offsetHeight !== 0;
            });
        trapFirst = trapFocusables.length ? trapFocusables[0] : null;
        trapLast = trapFocusables.length ? trapFocusables[trapFocusables.length - 1] : null;
    }

    function filterTabtTrapNav(e) {

        if (e.key === 'Tab' || e.keyCode === 9) {
            if (!trapFirst || !trapLast) return;
            if (e.shiftKey) {
                if (e.target === trapFirst) {
                    trapLast.focus();
                    e.preventDefault();
                }
            } else if (e.target === trapLast) {
                trapFirst.focus();
                e.preventDefault();
            }
        }
        if (e.key === 'Escape' || e.keyCode === 27) {

            const overlay = qs(SEL.overlay, root);
            if (overlay && overlay.classList.contains('is-activate')) {
                closeSignInOverlay();
            } else {
                disableTabTrap();
            }
        }
    }
    const enableTabTrap = () => {
        refreshTrapFocusables();
        window.addEventListener('keydown', filterTabtTrapNav);
    };
    const disableTabTrap = () => {
        window.removeEventListener('keydown', filterTabtTrapNav);
        trapFocusables = trapFirst = trapLast = null;
    };

    function initUniqueIds() {
        const openActMobile = qs(SEL.openActMobile);
        if (!openActMobile) return;
        const btn = qs('.btn-global-nav', openActMobile);
        if (!btn) return;
        const uid = btn.getAttribute('id') + '-mobile';
        btn.setAttribute('id', uid);
        const menu = qs('.dropdown-menu', openActMobile);
        if (menu) menu.setAttribute('aria-labelledby', uid);
    }

    function initResponsiveDrops(refs) {
        function constructDrops() {
            qsa('.navbar-top .navbar-nav .nav-item.active').forEach(function(item, index) {
                item.classList.add('dropdown');
                const link = qs(':scope > .nav-link', item);
                if (link) {
                    link.classList.add('dropdown-toggle');

                    const toggleId = 'navbarDropdownTopNav-' + index;
                    link.setAttribute('id', toggleId);
                    link.setAttribute('role', 'button');
                    link.setAttribute('data-bs-toggle', 'dropdown');
                    link.setAttribute('aria-haspopup', 'true');
                    link.setAttribute('aria-expanded', 'false');
                    const dropMenu = qs(':scope > .mobile-drop-menu', item);
                    if (dropMenu) dropMenu.setAttribute('aria-labelledby', toggleId);
                }
            });
            const mobileDropList = qs('.mobile-menu-toggle');
            if (mobileDropList) {
                qsa('.navbar-top .navbar-nav .nav-item:not(.active):not(.nav-util-links)')
                    .forEach(function(el) {
                        mobileDropList.appendChild(el);
                    });
            }
            const utilityNav = qs('.utility-nav');
            if (refs.bottomContainer && utilityNav) refs.bottomContainer.appendChild(utilityNav);

            const heroLogin = qs(SEL.heroLogin);
            if (heroLogin) {
                if (heroLogin.children.length > 0) {
                    const target = nextFind(refs.signInMobile, '.login-component');
                    if (target) {
                        clearChildren(target);
                        moveChildren(heroLogin, target);
                    }
                }
                clearChildren(heroLogin);
            }
        }

        function deconstructDrops() {
            const mobileDrop = qs('.mobile-drop');
            if (mobileDrop && mobileDrop.classList.contains('dropdown')) {
                const mainNav = qs('.main-nav');
                if (mainNav) qsa('.mobile-menu-toggle li').forEach(function(li) {
                    mainNav.appendChild(li);
                });

                qsa('.navbar-top .nav-item.mobile-drop .nav-link').forEach(function(link) {
                    link.classList.remove('dropdown-toggle');
                    ['data-bs-toggle', 'aria-haspopup', 'role', 'id', 'aria-expanded'].forEach(function(a) {
                        link.removeAttribute(a);
                    });
                });
                qsa('.navbar-top .nav-item.mobile-drop').forEach(function(item) {
                    item.classList.remove('dropdown');
                });

                qsa('.main-nav').forEach(function(nav) {

                    qsa(':scope > li', nav).sort(function(a, b) {
                        const pa = parseInt(a.getAttribute('data-pos'), 10);
                        const pb = parseInt(b.getAttribute('data-pos'), 10);
                        return (isNaN(pa) ? 0 : pa) - (isNaN(pb) ? 0 : pb);
                    }).forEach(function(li) {
                        nav.appendChild(li);
                    });
                });

                const topContainer = qs('.navbar-top .navbar-container');
                const utilityNav = qs('.utility-nav');
                if (topContainer && utilityNav) topContainer.appendChild(utilityNav);
                const mobileDropContainer = qs('.mobile-drop-menu');
                if (mobileDropContainer) mobileDropContainer.classList.remove('show');
            }

            const heroLogin = qs(SEL.heroLogin);
            if (heroLogin) {
                if (heroLogin.children.length === 0) {
                    const source = nextFind(refs.signInMobile, '.login-component');
                    if (source && source.children.length > 0) moveChildren(source, heroLogin);
                }
                clearChildren(nextFind(refs.signInMobile, '.login-component'));
            }
        }

        let lastIsMobile = null;

        function adjustForMobile(force) {
            const isMobile = window.innerWidth < 1024;
            if (!force && isMobile === lastIsMobile) return;
            lastIsMobile = isMobile;
            if (isMobile) constructDrops();
            else deconstructDrops();
        }

        let resizeScheduled = false;

        function onResize() {
            if (resizeScheduled) return;
            resizeScheduled = true;
            window.requestAnimationFrame(function() {
                resizeScheduled = false;
                adjustForMobile(false);
            });
        }

        window.addEventListener('load', function() {
            adjustForMobile(true);
        });
        window.addEventListener('resize', onResize);
    }

    function initBurger(refs) {
        if (!refs.toggler) return;
        refs.toggler.addEventListener('click', function() {
            const overlay = refs.getOverlay();
            if (overlay && overlay.classList.contains('is-activate') && refs.signInMobile) {
                refs.signInMobile.click();
            }
            this.classList.toggle('is-active');
            if (this.parentElement) this.parentElement.classList.toggle('is-activate');

            this.setAttribute('aria-expanded', this.classList.contains('is-active') ? 'true' : 'false');


            const bs5 = getBS5();
            const navbarBottomEl = qs(SEL.navbarBottom);
            if (navbarBottomEl && bs5 && bs5.Collapse) {
                bs5.Collapse.getOrCreateInstance(navbarBottomEl, {
                    toggle: false
                }).toggle();
            } else if (navbarBottomEl) {
                navbarBottomEl.classList.toggle('show');
            }

            qsa('.navbar .navbar-bottom .secondary-nav-item .dropdown-toggle')
                .forEach(function(el) {
                    el.setAttribute('aria-expanded', 'false');
                });
            qsa('.navbar .navbar-bottom .secondary-nav-item, .navbar .navbar-bottom .secondary-nav-item .dropdown-menu')
                .forEach(function(el) {
                    el.classList.remove('show');
                });

            qsa('.navbar-top .navbar-nav .nav-item.active .nav-link.dropdown-toggle:not(.main-nav-toggle)')
                .forEach(function(el) {
                    toggleAriaExpanded(el);
                });

            if (this.classList.contains('is-active')) enableTabTrap();
            else disableTabTrap();
        });
    }

    function initSignIn(refs) {
        if (refs.signInMobile) {
            refs.signInMobile.addEventListener('click', function() {
                if (refs.toggler && refs.toggler.parentElement && refs.toggler.parentElement.classList.contains('is-activate')) {
                    refs.toggler.click();
                }
                const overlay = refs.getOverlay();
                if (overlay) overlay.classList.toggle('is-activate');
                document.body.classList.toggle('is-activate');

                const mobileDropdown = nextFind(this, '.sign-in-dropdown');
                if (mobileDropdown && mobileDropdown.children.length === 0) {
                    moveChildren(nextFind(refs.signInDesktop, '.sign-in-dropdown'), mobileDropdown);
                }

                if (overlay && overlay.classList.contains('is-activate')) {
                    overlay.setAttribute('role', 'dialog');
                    overlay.setAttribute('aria-modal', 'true');
                    refs.signInReturnFocus = this;
                    activeOverlayRefs = refs;
                    enableTabTrap();
                    const closeBtn = qs(SEL.signInClose, overlay);
                    const firstFocusable = closeBtn ||
                        qs("input,button,select,textarea,a,[tabindex]:not([tabindex='-1'])", overlay);
                    if (firstFocusable) firstFocusable.focus();
                } else {
                    disableTabTrap();
                    if (refs.signInReturnFocus) {
                        refs.signInReturnFocus.focus();
                        refs.signInReturnFocus = null;
                    }
                }
            });
        }

        if (refs.signInDesktop) {
            refs.signInDesktop.addEventListener('click', function() {
                const desktopDropdown = nextFind(this, '.sign-in-dropdown');
                if (desktopDropdown && desktopDropdown.children.length === 0) {
                    moveChildren(nextFind(refs.signInMobile, '.sign-in-dropdown'), desktopDropdown);
                }
            });
        }

        if (refs.signInClose && refs.signInMobile) {
            refs.signInClose.addEventListener('click', function() {
                refs.signInMobile.click();
            });
        }

        qsa('.dropdown-menu', root).forEach(function(menu) {
            menu.addEventListener('click', function(event) {
                const isCloseIcon = /truist-signon-close-/.test((event.target && event.target.className) || '');
                if (isCloseIcon) {
                    activeOverlayRefs = refs;
                    closeSignInOverlay();
                } else {
                    event.stopPropagation();
                }
            });
        });
    }

    function initMiscLinks() {
        const spanishLinkDiv = qs('.langLink', root);
        if (spanishLinkDiv) {
            const base = spanishLinkDiv.getAttribute('href') || '';
            let path = window.location.pathname || '/';
            if (!/^\/[A-Za-z0-9\-._~%/]*$/.test(path)) {
                path = '/';
            }
            const url = base + path;
            spanishLinkDiv.setAttribute('href', url);
            spanishLinkDiv.setAttribute('data-href', url);
        }
    }

    function init(el) {
        root = (el instanceof Element) ? el : qs(SEL.root);
        if (!root) return;
        try {
            const signInMobile = qs(SEL.signInMobile);
            const refs = {
                toggler: qs(SEL.toggler, root),
                bottomContainer: qs(SEL.bottomContainer),
                signInMobile: signInMobile,
                signInDesktop: qs(SEL.signInDesktop),
                signInClose: qs(SEL.signInClose),
                getOverlay: (function() {
                    let cached = null;
                    return function() {
                        if (cached && document.contains(cached)) return cached;
                        if (!signInMobile) return null;
                        let sib = signInMobile.nextElementSibling;
                        while (sib && !sib.classList.contains('truist-signin-overlay')) sib = sib.nextElementSibling;
                        cached = sib;
                        return cached;
                    };
                })()
            };

            initUniqueIds();
            initResponsiveDrops(refs);
            initBurger(refs);
            initSignIn(refs);
            initMiscLinks();
            initAriaCurrent();
        } catch (e) {
            console.error('Error: Global Navigation functions: ' + (e && (e.message || String(e)) ? (e.message || String(e)) : 'unknown error'));
        }
    }

    return {
        init: init
    };
};

$('.truist-globalnav-nav-container').on('click:a11y', 'a[role="button"]', $.noop);
'use strict';

window.heroBannerComponent = function() {
    'use strict';

    var SEL = {
        banner: '.page-hero-banner',
        modalTrigger: '.page-hero-banner a.modalWindow',
        whiteOpacity: '.orion-hero-white-opacity',
        purpleOpacity: '.orion-hero-purple-opacity'
    };

    var qs = function(sel, ctx) {
        return (ctx || document).querySelector(sel);
    };
    var qsa = function(sel, ctx) {
        return Array.prototype.slice.call((ctx || document).querySelectorAll(sel));
    };

    var getBS5 = function() {
        return window.__bootstrap5__;
    };

    var _private = {

        init: function(heroBannerEl) {
            if (!heroBannerEl || !(heroBannerEl instanceof Element)) {
                return;
            }
            if (!heroBannerEl.classList.contains('page-hero-banner') &&
                !heroBannerEl.querySelector(SEL.banner)) {
                return;
            }
            try {
                _private.initBackgroundColor();
                var bs5 = getBS5();
                if (bs5) {
                    _private.initModalTriggers(bs5);
                } else {
                    document.addEventListener('bootstrap5:ready', function(event) {
                        _private.initModalTriggers(event.detail || getBS5());
                    });
                }
            } catch (e) {
                console.error('HeroBanner Component: init error: ' + (e && (e.message || String(e)) ? (e.message || String(e)) : 'unknown error'));
            }
        },

        initBackgroundColor: function() {
            var windowSize = window.matchMedia('(max-width: 1024px)');
            var whiteBackgrounds = qsa(SEL.whiteOpacity);
            var purpleBackgrounds = qsa(SEL.purpleOpacity);
            var applyColor = function(e) {
                _private.applyBackgroundColor(e, whiteBackgrounds, purpleBackgrounds);
            };
            applyColor(windowSize);
            windowSize.addEventListener('change', applyColor);
        },

        removeOpacityClass: function(el) {
            var classes = Array.prototype.slice.call(el.classList);
            classes.forEach(function(cls) {
                if (cls.indexOf('orion-hero-opacity-') === 0) {
                    el.classList.remove(cls);
                }
            });
        },

        applyBackgroundColor: function(e, whiteBackgrounds, purpleBackgrounds) {
            if (e.matches) {
                whiteBackgrounds.forEach(function(el) {
                    _private.removeOpacityClass(el);
                });
                purpleBackgrounds.forEach(function(el) {
                    _private.removeOpacityClass(el);
                });
            } else {
                whiteBackgrounds.forEach(function(el) {
                    var raw = el.getAttribute('data-opacity-level');
                    var level = parseInt(raw, 10);
                    if (!isNaN(level) && level >= 1 && level <= 10) {
                        _private.removeOpacityClass(el);
                        el.classList.add('orion-hero-opacity-' + level);
                    }
                });
                purpleBackgrounds.forEach(function(el) {
                    var raw = el.getAttribute('data-opacity-level');
                    var level = parseInt(raw, 10);
                    if (!isNaN(level) && level >= 1 && level <= 10) {
                        _private.removeOpacityClass(el);
                        el.classList.add('orion-hero-opacity-' + level);
                    }
                });
            }
        },

        initModalTriggers: function(bs5) {
            qsa(SEL.modalTrigger).forEach(function(el) {
                el.setAttribute('role', 'button');
                el.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter' || e.key === ' ' || e.keyCode === 13 || e.keyCode === 32) {
                        e.preventDefault();
                        var targetId = el.getAttribute('data-bs-target') || '';
                        if (/^#[a-zA-Z0-9_-]+$/.test(targetId)) {
                            var modalEl = qs(targetId);
                            if (modalEl && bs5 && bs5.Modal) {
                                bs5.Modal.getOrCreateInstance(modalEl).toggle();
                            }
                        }
                    }
                });
            });
        }

    };

    return {
        init: _private.init
    };
};


$(document).ready(function() {
    const CAROUSEL_ITEM_CLASS = '.carousel-item';
    const CAROUSEL_CLASS_ACTIVE = '.carousel-item.active';
    const CAROUSEL_CLASS_ACTIVE_SP = ' .carousel-item.active';
    const CAROUSEL_CONTROL_PREV_CLASS = " .carousel-control-prev";
    const CAROUSEL_CONTROL_NEXT_CLASS = " .carousel-control-next";
    const CAROUSEL_INDICATOR_LI_CLASS = ".carousel-indicators li";
    const CAROUSEL_INDICATOR_LI_CLASS_SP = " .carousel-indicators li";
    const CAROUSEL_INDICATOR_LI_ACTIVE_CLASS = ".carousel-indicators li.active";
    const ARIA_HIDDEN = 'aria-hidden';
    const CAROUSEL_INNER_ITEM_CLASS = '.carousel-inner .carousel-item';
    const DIV_SR_CLASS = 'div.sr-only';
    $('.cmp-genericcarousel').each(function(ev) {
        var genCarouselID = $(this).find('.generic-carousel-component-instance').attr("id");
        var genCarouselObj = $("#" + genCarouselID);
        var totalSlides_genCarousel = $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).length;
        var currentSlide_genCarousel = $("#" + genCarouselID + CAROUSEL_CLASS_ACTIVE_SP).index() + 1;

        var $genCarouselPrevButton;
        var $genCarouselNextButton;

        $genCarouselPrevButton = $("#" + genCarouselID + CAROUSEL_CONTROL_PREV_CLASS);
        $genCarouselNextButton = $("#" + genCarouselID + CAROUSEL_CONTROL_NEXT_CLASS);


        $("#" + genCarouselID + CAROUSEL_INDICATOR_LI_CLASS_SP).html(currentSlide_genCarousel + "<span>&nbsp;of&nbsp;</span>" + totalSlides_genCarousel);

        //Hide the carousel controls for smaller view port
        if (window.outerWidth <= 896) {
            $("#" + genCarouselID + CAROUSEL_CONTROL_NEXT_CLASS).attr("tabindex", "0");
            $("#" + genCarouselID + CAROUSEL_CONTROL_PREV_CLASS).attr("tabindex", "0");
        } else {
            $("#" + genCarouselID + CAROUSEL_CONTROL_NEXT_CLASS).attr("tabindex", "0");
            $("#" + genCarouselID + CAROUSEL_CONTROL_PREV_CLASS).attr("tabindex", "0");
        }
        $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
        $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
        genCarouselObj.bind("slid.bs.carousel", function() {

            $('#' + genCarouselID + CAROUSEL_INDICATOR_LI_CLASS_SP).each(function() {
                if ($(this).parent().hasClass('moreThan5slides') && $(this).hasClass("active")) {
                    $('#' + genCarouselID + ' ul.carousel-indicators li').empty();
                    $(this).html($('#' + genCarouselID + CAROUSEL_CLASS_ACTIVE_SP).index() + 1 + "<span>&nbsp;of&nbsp;</span>" + totalSlides_genCarousel)
                }
            });
        });
        checkGenCarouselItem(genCarouselObj, $genCarouselPrevButton, $genCarouselNextButton);
        genCarouselObj.on("slid.bs.carousel", "", function() {
            checkGenCarouselItem(genCarouselObj, $genCarouselPrevButton, $genCarouselNextButton);
        });

        genCarouselObj.find(".carousel-indicators li").keydown(function(e) {
            if ((e.which === 13 || e.which === 32) && $(this).parent().hasClass('moreThan5slides')) {
                //ADA fix code writtern for pagination
                $(CAROUSEL_INDICATOR_LI_CLASS).attr({
                    "tabindex": "0",
                    "aria-selected": "false"
                }).removeClass("active");
                setTimeout(function() {
                    $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                    $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
                    $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).focus();
                }, 1000);

                $(this).addClass("active").attr("tabindex", "0");
                $(this).click();
                e.preventDefault();
            } else if (e.which === 13 || e.which === 32 || e.which === 37 || e.which === 39) {
                // Code writtern for carousel indicators
                // Code writtern for carousel indicators
                $(CAROUSEL_INDICATOR_LI_CLASS).attr({
                    "tabindex": "-1",
                    "aria-selected": "false"
                }).removeClass("active");
                // $(CAROUSEL_INDICATOR_LI_CLASS).attr({"tabindex": "0", "aria-selected": "false"}).removeClass("active");
                setTimeout(function() {
                    $(this).addClass("active");
                    genCarouselObj.find(CAROUSEL_INDICATOR_LI_ACTIVE_CLASS).attr({
                        "tabindex": "0",
                        "aria-selected": "true"
                    }).focus();
                }, 300);

                setTimeout(function() {
                    $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                    $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
                }, 1000);
                $(this).click();
                e.preventDefault();
            }
        });
        var $genCarouselPrevIcon = "#" + genCarouselID + " .carousel-control-prev-icon";
        var $genCarouselNextIcon = "#" + genCarouselID + " .carousel-control-next-icon";
        var $genCarouselSlideInd = "#" + genCarouselID + CAROUSEL_INDICATOR_LI_CLASS_SP;

        $($genCarouselPrevIcon).click(function() {
            genCarouselObj.find(CAROUSEL_INDICATOR_LI_CLASS).siblings().removeClass("active").attr({
                "tabindex": "-1",
                "aria-selected": "false"
            });
            setTimeout(function() {
                genCarouselObj.find(CAROUSEL_INDICATOR_LI_ACTIVE_CLASS).attr({
                    "tabindex": "0",
                    "aria-selected": "true"
                });
            }, 300);

            setTimeout(function() {
                $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
            }, 1000);
        });

        $($genCarouselNextIcon).click(function() {
            genCarouselObj.find(CAROUSEL_INDICATOR_LI_CLASS).siblings().removeClass("active").attr({
                "tabindex": "-1",
                "aria-selected": "false"
            });
            setTimeout(function() {
                genCarouselObj.find(CAROUSEL_INDICATOR_LI_ACTIVE_CLASS).attr({
                    "tabindex": "0",
                    "aria-selected": "true"
                });
            }, 300);

            setTimeout(function() {
                $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
            }, 1000);
        });

        $($genCarouselSlideInd).click(function() {
            genCarouselObj.find(CAROUSEL_INDICATOR_LI_CLASS).siblings().removeClass("active").attr({
                "tabindex": "-1",
                "aria-selected": "false"
            });
            setTimeout(function() {
                $(this).addClass("active");
                genCarouselObj.find(CAROUSEL_INDICATOR_LI_ACTIVE_CLASS).attr({
                    "tabindex": "0",
                    "aria-selected": "true"
                });
            }, 300);

            setTimeout(function() {
                $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
            }, 1000);
        });

        $("#" + genCarouselID + CAROUSEL_CONTROL_PREV_CLASS).keydown(function(e) {
            if (e.which === 13 || e.which === 32) {
                $("#" + genCarouselID).find(CAROUSEL_INDICATOR_LI_CLASS).siblings().attr({
                    "tabindex": "-1",
                    "aria-selected": "false"
                });
                setTimeout(function() {
                    $("#" + genCarouselID).find(CAROUSEL_INDICATOR_LI_ACTIVE_CLASS).attr({
                        "tabindex": "0",
                        "aria-selected": "true"
                    });
                }, 100);
                setTimeout(function() {
                    $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                    $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
                }, 1000);
                e.preventDefault();
                $(this).click();
            }
        });
        $("#" + genCarouselID + CAROUSEL_CONTROL_NEXT_CLASS).keydown(function(e) {
            if (e.which === 13 || e.which === 32) {
                $("#" + genCarouselID).find(CAROUSEL_INDICATOR_LI_CLASS).siblings().attr({
                    "tabindex": "-1",
                    "aria-selected": "false"
                });
                setTimeout(function() {
                    $("#" + genCarouselID).find(CAROUSEL_INDICATOR_LI_ACTIVE_CLASS).attr({
                        "tabindex": "0",
                        "aria-selected": "true"
                    });
                }, 100);
                setTimeout(function() {
                    $("#" + genCarouselID).find(CAROUSEL_ITEM_CLASS).attr(ARIA_HIDDEN, 'true').find('a').attr('tabindex', '-1');
                    $("#" + genCarouselID).find(CAROUSEL_CLASS_ACTIVE).attr(ARIA_HIDDEN, 'false').find('a').attr('tabindex', '0');
                }, 1000);
                e.preventDefault();
                $(this).click();
            }
        });

    });
});

function checkGenCarouselItem(genCarouselObj, $genCarouselPrevButton, $genCarouselNextButton) {
    var genSronlyTextPrev = "Previous Slide";
    var genSronlyTextNext = "Next Slide";
    const CAROUSEL_INNER_ITEM_CLASS = '.carousel-inner .carousel-item';
    const DIV_SR_CLASS = 'div.sr-only';
    if (genCarouselObj.find(".carousel-inner .carousel-item:first").hasClass("active")) {
        if (genCarouselObj.find(CAROUSEL_INNER_ITEM_CLASS).length === 1) {
            $genCarouselPrevButton.removeClass("d-flex").addClass("d-none");
            $genCarouselNextButton.removeClass("d-flex").addClass("d-none");
        } else {
            $genCarouselNextButton.removeClass("d-none").addClass("d-flex");
            $genCarouselPrevButton.children(DIV_SR_CLASS).text(genSronlyTextPrev);
            $genCarouselNextButton.children(DIV_SR_CLASS).text(genSronlyTextNext);
        }
    } else if (genCarouselObj.find(".carousel-inner .carousel-item:last").hasClass("active")) {
        $genCarouselPrevButton.removeClass("d-none").addClass("d-flex");
        $genCarouselPrevButton.children(DIV_SR_CLASS).text(genSronlyTextPrev);
        $genCarouselNextButton.children(DIV_SR_CLASS).text(genSronlyTextNext);

    } else {
        $genCarouselPrevButton.addClass("d-flex");
        $genCarouselPrevButton.children(DIV_SR_CLASS).text(genSronlyTextPrev);
        $genCarouselNextButton.addClass("d-flex");
        $genCarouselNextButton.children(DIV_SR_CLASS).text(genSronlyTextNext);
    }

};

$(document).ready(function() {
    const OptionsReveal = $('.options-reveal-comp');
    if (OptionsReveal.length === 0) {
        return;
    } else {
        function sectionChange(dropdownid, keepsection, s) {
            var $root = $(dropdownid).closest(".options-reveal-comp");
            if (keepsection.startsWith("/") || keepsection.startsWith("http")) {
                if ($('option[value="' + keepsection + '"]').attr("data-new-tab") == "true") {
                    window.open(keepsection, "_blank");
                } else {
                    window.location.href = keepsection;
                }
            } else if (keepsection != "#") {
                $root.find(".reveal-content").hide();
                $root.find(".actual-content").show();
                for (i = 0; i < dropdownid.length; i++) {
                    if (document.getElementById(dropdownid[i].value)) {
                        $("#" + dropdownid[i].value).addClass("section-change-hide")
                        $("#" + dropdownid[i].value).removeClass("section-change-show")
                    }
                }
                $("#" + keepsection).removeClass("section-change-hide")
                $("#" + keepsection).addClass("section-change-show")
                jump('options-unveil', s)
            } else if (keepsection == "#") {
                $root.find(".reveal-content").hide();
                $root.find(".default-content").show();
            }
        }

        function jump(h, s) {
            var top = document.getElementById(h).offsetTop,
                left = document.getElementById(h).offsetLeft;
            var doc = document.documentElement;
            var elmTop = (window.pageYOffset || doc.scrollTop) - (doc.clientTop || 0);
            var animator = createAnimator({
                start: [0, elmTop],
                end: [left, top],
                duration: 1000
            }, function(vals) {
                window.scrollTo(vals[0], vals[1]);
            });

            //run
            animator();
        }

        //Animator
        //Licensed under the MIT License
        function createAnimator(config, callback, done) {
            if (typeof config !== "object") throw new TypeError("Arguement config expect an Object");

            var start = config.start,
                mid = $.extend({}, start), //clone object
                math = $.extend({}, start), //precalculate the math
                end = config.end,
                duration = config.duration || 1000,
                startTime, endTime;

            function precalculate(a, b, c, d) {
                return [(b - d) / (a - c), (a * d - b * c) / (a - c)];
            }

            function calculate(key, t) {
                return t * math[key][0] + math[key][1];
            }

            function step() {
                var t = Date.now();
                var val = end;
                if (t < endTime) {
                    val = mid;
                    for (var key in mid) {
                        mid[key] = calculate(key, t);
                    }
                    callback(val);
                    requestAnimationFrame(step);
                } else {
                    callback(val);
                    done && done();
                }
            }

            return function() {
                startTime = Date.now();
                endTime = startTime + duration;

                for (var key in math) {
                    math[key] = precalculate(startTime, start[key], endTime, end[key]);
                }
                step();
            }
        }

        $(".options-reveal-comp").each(function(ev) {
            var $root = $(this);
            var select = $root.find(".select-content")[0];
            $(select).change(function() {
                $(this).closest(".options-reveal-comp").find(".go-button").attr("data-wa-linkname", $(this).find("option:selected").text().trim());
            });
            $root.find(".go-button").click(function() {
                sectionChange(select, select.value, this);
            });
        });

        //update arrow open select open
        $(document).mouseup(function(e) {
            //conditional check
            let select = $('.truist-drop-down-box select');
            let selectWrapper = $('.truist-select-wrapper');
            if (!$(e.target).is(select) && selectWrapper.hasClass('truist-select-wrapper-open')) {
                $('.truist-select-wrapper').removeClass('truist-select-wrapper-open');
            }
        });

        openOnSelect = function() {
            let select = $('.truist-drop-down-box select');
            select.click(function() {
                $('.truist-select-wrapper').toggleClass('truist-select-wrapper-open');
            });
        }

        openOnSelect();
    }
});
$(document).ready(function() {
    $('.ori-tabs__tab:not(.is-active) button').attr('aria-selected', false);
    $('.ori-tabs__tab.is-active button').attr('aria-selected', true);
    $('.ori-tabs__panel').attr({
        'tabindex': '-1',
        'aria-hidden': 'true'
    });
    $('.ori-tabs__panel.is-active').attr({
        'tabindex': '0',
        'aria-hidden': 'false'
    });
    $('.ori-tabs__scrollable-button').removeAttr('aria-selected');

    $('.truist-tabs .ori-tabs__list .ori-tabs__tab').keyup(function(e) {
        let buttonSelected = $('.truist-tabs .ori-tabs__list .ori-tabs__tab button.is-active');
        let buttonSelectedNext = $(buttonSelected).closest('.ori-tabs__tab').next().find(".ori-tabs__tab__button");
        let buttonSelectedPrev = $(buttonSelected).closest('.ori-tabs__tab').prev().find(".ori-tabs__tab__button");
        let activePanelCall = $(buttonSelected).attr('data-target');
        activePanelCall = activePanelCall.substring(activePanelCall.indexOf('-') + 1);
        if (e.which === 39) {
            if (buttonSelected) {
                if (buttonSelectedNext.length > 0) {
                    console.log($("#panel-" + activePanelCall).next());
                    $(buttonSelectedNext).closest('.ori-tabs__tab').addClass('is-active');
                    $(buttonSelectedNext).addClass('is-active').attr({
                        'aria-selected': 'true',
                        tabindex: '0'
                    }).addClass('is-active').focus();
                    $(buttonSelectedNext).closest('.ori-tabs__tab').siblings().removeClass('is-active').find('.ori-tabs__tab__button').removeClass('is-active').attr({
                        'aria-selected': 'false',
                        tabindex: '-1'
                    }).blur();
                    $('.ori-tabs__panel').removeClass('is-active').attr({
                        'aria-hidden': 'true',
                        tabindex: '-1'
                    });
                    $("#panel-" + activePanelCall).next().addClass('is-active').attr({
                        'aria-hidden': 'false',
                        tabindex: '0'
                    });
                }
            }
        } else if (e.which === 37) {
            if (buttonSelected) {
                if (buttonSelectedPrev.length > 0) {
                    $(buttonSelectedPrev).closest('.ori-tabs__tab').addClass('is-active')
                    $(buttonSelectedPrev).addClass('is-active').attr({
                        'aria-selected': 'true',
                        tabindex: '0'
                    }).addClass('is-active').focus();
                    $(buttonSelectedPrev).closest('.ori-tabs__tab').siblings().removeClass('is-active').find('.ori-tabs__tab__button').removeClass('is-active').attr({
                        'aria-selected': 'false',
                        tabindex: '-1'
                    }).blur();
                    $('.ori-tabs__panel').removeClass('is-active').attr({
                        'aria-hidden': 'true',
                        tabindex: '-1'
                    });
                    $("#panel-" + activePanelCall).prev().addClass('is-active').attr({
                        'aria-hidden': 'false',
                        tabindex: '0'
                    });
                }
            }
        }
    });
});

const OriTabs = (function(props) {
    const _private = {
        Cache: {},

        cacheDom() {
            _private.Cache.$parent = $('.js-ori-tabs');
            _private.Cache.$tab = $('.js-ori-tabs__tab');
            _private.Cache.$tabButton = $('.js-ori-tabs__tab__button')
            _private.Cache.$panel = $('.js-ori-tabs__panel');
            _private.Cache.$tabList = $('.js-ori-tabs__list');
            _private.Cache.$scrollLeft = $('.js-scrollable-left');
            _private.Cache.$scrollRight = $('.js-scrollable-right');

        },

        bindEvents() {
            _private.Cache.$tabButton.on('click', function(e) {
                _private.changePanel(_private.getPanel($(this)));
            });

            $(window).on('focusin', function(e) {
                if ($('.js-ori-tabs__tab__button').has(':focus')) {
                    _private.adjustFocus(e.target);
                }
            })

            _private.Cache.$scrollRight.on('click', function() {
                _private.getNextTab($(this));
            });

            _private.Cache.$scrollLeft.on('click', function() {
                _private.getPrevTab($(this));
            });

            _private.Cache.$tabList.on('scroll', function() {
                _private.addButtons($(this));
            });

            $(window).resize(function() {
                $('.js-ori-tabs__list').each(function() {
                    _private.checkWidth($(this));
                });
            });
        },

        render() {
            _private.setOrder($('.js-ori-tabs__tab'));
            _private.addButtons($('.js-scrollable-left'));
            _private.addButtons($('.js-scrollable-right'))
            _private.checkWidth($('.js-ori-tabs__list'));
        },

        getPanel(tabSelector) {
            return $(tabSelector).attr('data-target');
        },

        setOrder(elem) {
            $(elem).each(function(i) {
                $(this).attr('data-order', i);
            });
        },

        addButtons(elem) {
            let $this = $(elem);
            let elemWidth = $this.outerWidth();
            let scrollWidth = $this.get(0).scrollWidth;
            let $elemScroll = $this.scrollLeft();
            let $firstChildWidth = $this.children().first().outerWidth() / 2;
            let $leftButton = $this.siblings('.js-scrollable-left');
            let $rightButton = $this.siblings('.js-scrollable-right');

            if ($elemScroll >= $firstChildWidth) {
                $leftButton.removeClass('ori-display--none');
            } else {
                $leftButton.addClass('ori-display--none');
            }
            if (((scrollWidth - $elemScroll) >= (elemWidth - 1)) && ((scrollWidth - $elemScroll) <= (elemWidth + 1))) {
                $rightButton.addClass('ori-display--none');
            } else {
                $rightButton.removeClass('ori-display--none');
            }
        },

        getRightWidth(elem) {
            return $(elem).offset().left + $(elem).width();
        },

        checkWidth(e) {
            let $this = $(e);
            let $thisWidth = $this[0].scrollWidth;
            let $scrollRight = $this.siblings('.js-scrollable-right');
            let $scrollLeft = $this.siblings('.js-scrollable-left');
            let $parent = $this.parents('.js-ori-tabs');
            let $parentWidth = $parent.width();
            if ($thisWidth > $parentWidth) {
                $scrollRight.removeClass('ori-display--none');
            }

            if ($thisWidth <= $parentWidth) {
                $scrollRight.addClass('ori-display--none');
                $scrollLeft.addClass('ori-display--none');
            }
        },

        changePanel(target) {
            const $target = $(target);
            const $targetSiblings = $target.siblings('.js-ori-tabs__panel');
            const triggerID = $target.attr('data-trigger');
            const $tab = $(triggerID);
            const $tabParent = $tab.parent('.js-ori-tabs__tab');
            const $tabSiblings = $tabParent.siblings('.js-ori-tabs__tab');
            const $buttonSiblings = $tabSiblings.children('.js-ori-tabs__tab__button');

            $targetSiblings
                .removeClass('is-active')
                .attr('aria-hidden', true)
                .removeAttr('tabindex', '0')
                .attr('tabindex', '-1');

            $target
                .addClass('is-active')
                .attr('aria-hidden', false)
                .removeAttr('tabindex', '-1')
                .attr('tabindex', '0');

            $tab
                .addClass('is-active')
                .attr('aria-pressed', true)
                .attr('aria-selected', true);

            $tabParent
                .addClass('is-active');


            $tabSiblings
                .removeClass('is-active')
                .attr('aria-selected', false);


            $buttonSiblings
                .removeClass('is-active')
                .attr('aria-pressed', false);
        },

        adjustFocus(elem) {

        },

        getPrevTab(target) {
            //alert("getPrev")
            const $target = $(target);
            const $listParent = $target.siblings('.js-ori-tabs__list');

            let newScrollLeftValue = $listParent.scrollLeft() - $listParent.width() + 50;

            if (newScrollLeftValue < 50) {
                newScrollLeftValue = 0;
            }

            $listParent.animate({
                scrollLeft: newScrollLeftValue
            });

            _private.addButtons($listParent);
        },

        getNextTab(target) {
            const $target = $(target);
            const $listParent = $target.siblings('.js-ori-tabs__list');
            const maxScrollLeftValue = $listParent.get(0).scrollWidth - $listParent.width();
            let newScrollLeftValue = $listParent.scrollLeft() + $listParent.width() - 50;

            if (newScrollLeftValue >= maxScrollLeftValue) {
                newScrollLeftValue = maxScrollLeftValue;
            }

            $listParent.animate({
                scrollLeft: newScrollLeftValue
            });

            _private.addButtons($listParent);
        },

        init() {
            _private.cacheDom();
            _private.render();
            _private.bindEvents();
        }
    }

    const _public = {
        init: _private.init,
        getPanel: _private.getPanel,
        changePanel: _private.changePanel,
        getPrevTab: _private.getPrevTab,
        getNextTab: _private.getNextTab
    }


    return Object.assign(
        _public,
        props
    );
});

