$(async () => {
    if (!$('.comparison__container').length) return;

    try {
        await LibLoader.get({
                uri: '/etc/clientlibs/truist-global/clientlibs/js/slick.js',
                verifier: () => !!$.fn.slick
            },
            '/etc/clientlibs/truist-global/clientlibs/css/slick-theme.css',
            '/etc/clientlibs/truist-global/clientlibs/css/slick.css'
        );

        await LibLoader.get({
            uri: '/etc/clientlibs/truist-global/clientlibs/js/tab-selector-utils.js',
            verifier: () => !!selectTruistTabsSamePage
        })
    } catch (err) {
        // CWE-117 (SEC-CWE117-S03): use sanitizing Logger; fall back to no-op.
        if (typeof window !== 'undefined' && window.Logger && typeof window.Logger.error === 'function') {
            window.Logger.error('filltabs error', err && err.message);
        }
    }

    if ($(".comparison__container")[0]) {
        $(document).ready(function() {
            let mobileContainers = document.querySelectorAll(".fill-tabs--content-mobile *")
            mobileContainers.forEach((mobileContainer) => {
                let containerID = mobileContainer.getAttribute("id")
                let ariaControls = mobileContainer.getAttribute("aria-controls")
                let dataAttributeID = mobileContainer.getAttribute("data-target")
                let dataAttributeParentID = mobileContainer.getAttribute("data-parent")
                let ariaLabelledByAttribute = mobileContainer.getAttribute("aria-labelledby")
                let dataIdAttribute = mobileContainer.getAttribute("data-id-selector")
                let forAttribute = mobileContainer.getAttribute("for")
                let nameAttribute = mobileContainer.getAttribute("name")
                if (containerID) {
                    mobileContainer.setAttribute("id", `${containerID}--fill-tab-mobile`)
                }
                if (ariaControls) {
                    mobileContainer.setAttribute("aria-controls", `${ariaControls}--fill-tab-mobile`)
                }
                if (dataAttributeID) {
                    mobileContainer.setAttribute("data-target", `${dataAttributeID}--fill-tab-mobile`)
                }
                if (dataAttributeParentID) {
                    mobileContainer.setAttribute("data-parent", `${dataAttributeParentID}--fill-tab-mobile`)
                }
                if (ariaLabelledByAttribute) {
                    mobileContainer.setAttribute("aria-labelledby", `${ariaLabelledByAttribute}--fill-tab-mobile`)
                }
                if (dataIdAttribute) {
                    mobileContainer.setAttribute("data-id-selector", `${dataIdAttribute}--fill-tab-mobile`)
                }
                if (forAttribute) {
                    mobileContainer.setAttribute("for", `${forAttribute}--fill-tab-mobile`)
                }
                if (nameAttribute) {
                    mobileContainer.setAttribute("name", `${nameAttribute}--fill-tab-mobile`)
                }
            })

            // get all mobile tab containers
            const tabComponentsToUpdate = document.querySelectorAll(".fill-tabs--content-mobile");

            // observe each of the mobile tab containers
            tabComponentsToUpdate.forEach((tabComponentToUpdate) => {
                let elementId = tabComponentToUpdate.getAttribute("id")
                let parentIDContainer = elementId.replace("content-mobile", "nav")
                let activeSlideIndex = $(`#${parentIDContainer}`).attr("data-activeindex");
                $(`#${elementId}`).slick({
                    initialSlide: parseInt(activeSlideIndex),
                    dots: true,
                    accessibility: true,
                    focusOnSelect: true,
                    arrows: false,
                    swipe: true,
                    mobileFirst: true,
                    adaptiveHeight: true
                })
                // set the the height of .slick-list to auto when an accordion button is clicked inside of the fill tabs
                // otherwise all of the accordion content will not be visible because the height of the slick card will not adjust
                const accordionButtons = document.querySelectorAll(`#${elementId} .accordion-card-header`)
                const slickListWithAccordion = document.querySelector(`#${elementId} .slick-list`)

                function updateSlickCardHeight(newHeight) {
                    slickListWithAccordion.style.height = newHeight + "px"
                    slickListWithAccordion.setAttribute('tabindex', 0).focus();
                }

                accordionButtons.forEach((accordionButton) => {
                    const accordionFillTabObserverConfig = {
                        attributes: true,
                        childList: true,
                        subtree: true
                    };
                    const callback = function(mutationsList, observer) {
                        for (const mutation of mutationsList) {
                            if (mutation.type === 'attributes') {
                                if (mutation.attributeName === "class") {
                                    let classUpdated = mutation.target.classList
                                    if (classUpdated.contains("collapse")) {
                                        updateSlickCardHeight(document.querySelector(`#${elementId} .slick-current`).offsetHeight)
                                    }
                                }
                            }
                        }
                    };
                    // Create an observer instance linked to the callback function
                    const accordionFillTabObserver = new MutationObserver(callback);
                    // Start observing the target node for configured mutations
                    accordionFillTabObserver.observe(accordionButton.nextElementSibling, accordionFillTabObserverConfig);
                });
                //Assign fill tabs name to mobile silder dots aria-lable for screen reader users
                setTimeout(function() {
                    $('.slick-dots').find('li').each(function(i) {
                        var fillTabsName = $(this).parents().find('ul.comparison-nav__link-container li a').map(function() {
                            return $(this).text().trim();
                        }).get();

                        $(this).find('button').attr({
                            'aria-label': 'Slide for ' + fillTabsName[i]
                        });
                    })
                }, 2500);
            });

            $(".comparison-nav__container li a").click(function(e) {
                e.preventDefault();
            });
            $('.comparison-nav__container li').click(function() {
                $(this).addClass('active');
                $(this).siblings().removeClass('active');
                $(this).find('.comparison-nav__link').attr('aria-selected', 'true');
                $(this).find('.comparison-nav__link').attr('tabindex', '0');
                $(this).siblings().find('.comparison-nav__link').attr('aria-selected', 'false');
                $(this).siblings().find('.comparison-nav__link').attr('tabindex', '-1');

                var tabsId = $(this).closest(".comparison__container").attr("id");
                $('#' + tabsId).find('.fill-tabs--tabcontent').removeClass('active');

                var tabid = $(this).find("a").attr("href");
                $(tabid).addClass('active');
            });

            $('.comparison-nav__container li').keydown(function(e) {
                let liSelected = $('.comparison-nav__container li.active');
                let liSelectedNext = $(liSelected).next();
                let liSelectedPrev = $(liSelected).prev();
                if (e.which === 39) {
                    if (liSelected) {
                        if (liSelectedNext.length > 0) {
                            $(liSelectedNext).addClass('active');
                            $(liSelectedNext).siblings().removeClass('active');
                            $(liSelectedNext).find('.comparison-nav__link').attr('aria-selected', 'true');
                            $(liSelectedNext).find('.comparison-nav__link').attr('tabindex', '0');
                            $(liSelectedNext).find('.comparison-nav__link').focus();
                            $(liSelectedNext).siblings().find('.comparison-nav__link').attr('aria-selected', 'false');
                            $(liSelectedNext).siblings().find('.comparison-nav__link').attr('tabindex', '-1');
                            $(liSelectedNext).siblings().find('.comparison-nav__link').blur();

                            var tabsId = $(liSelectedNext).closest(".comparison__container").attr("id");
                            $('#' + tabsId).find('.fill-tabs--tabcontent').removeClass('active');

                            var tabid = $(liSelectedNext).find("a").attr("href");
                            $(tabid).addClass('active');
                        }
                    }
                } else if (e.which === 37) {
                    if (liSelected) {
                        if (liSelectedPrev.length > 0) {
                            $(liSelectedPrev).addClass('active');
                            $(liSelectedPrev).siblings().removeClass('active');
                            $(liSelectedPrev).find('.comparison-nav__link').attr('aria-selected', 'true');
                            $(liSelectedPrev).find('.comparison-nav__link').attr('tabindex', '0');
                            $(liSelectedPrev).find('.comparison-nav__link').focus();
                            $(liSelectedPrev).siblings().find('.comparison-nav__link').attr('aria-selected', 'false');
                            $(liSelectedPrev).siblings().find('.comparison-nav__link').attr('tabindex', '-1');
                            $(liSelectedPrev).siblings().find('.comparison-nav__link').blur();

                            var tabsId = $(liSelectedPrev).closest(".comparison__container").attr("id");
                            $('#' + tabsId).find('.fill-tabs--tabcontent').removeClass('active');

                            var tabid = $(liSelectedPrev).find("a").attr("href");
                            $(tabid).addClass('active');
                        }
                    }
                }
            });
        });
    } else {
        return;
    }
});

