'use strict';
window.textLSComponent = function() {
    let lightStreamEnabled, lightStreamPurpose;
    const _private = {
        init: function(textComponentStr) {
            try {
                lightStreamEnabled = textComponentStr.data("lightstream") ? textComponentStr.data("lightstream") : '';
                lightStreamEnabled && CommonUtils.initPlaceholderLinks(textComponentStr);
                lightStreamEnabled && (_private.doTextComponentFunctions(textComponentStr));
            } catch (e) {
                console.log("Text Component : Error with lightstream data process: " + e);
            }
        },
        doTextComponentFunctions: (textComponentStr) => {
            lightStreamPurpose = textComponentStr.data('loanpurpose') ? textComponentStr.data('loanpurpose') : '';
            lsiRatesLoadWait(() => lsiEnabled === true, () => lsiRetriveRateRanges(lightStreamPurpose, textComponentStr, '.tru-txt-comp-clone', '.tru-txt-comp', '.text-lsc-loader'));
        },
    };
    const _public = {
        init: _private.init,
    };
    return _public;
};



jQuery(document).ready(function($) {
    const comparisonChart = $(".cd-products-comparison-table");
    if (comparisonChart.length === 0) {
        return
    } else {

        function productsTable(element) {
            this.element = element;
            this.table = this.element.children(".cd-products-table");
            this.tableHeight = this.table.height();
            this.productsWrapper = this.table.children(".cd-products-wrapper");
            this.tableColumns = this.productsWrapper.children(".cd-products-columns");
            this.products = this.tableColumns.children(".product");
            this.productsNumber = this.products.length;
            this.productWidth = this.products.eq(0).width();
            this.productsTopInfo = this.table.find(".top-info");
            this.featuresTopInfo = this.table
                .children(".features")
                .children(".top-info");
            this.topInfoHeight = this.featuresTopInfo.innerHeight() + 30;
            this.leftScrolling = false;
            this.filterBtn = this.element.find(".filter");
            this.resetBtn = this.element.find(".reset");
            (this.filtering = false), (this.selectedproductsNumber = 0);
            this.filterActive = false;
            this.navigation = this.table.children(".cd-table-navigation");
            this.bindEvents();
        }
        productsTable.prototype.bindEvents = function() {
            var self = this;
            self.productsWrapper.on("scroll", function() {
                if (!self.leftScrolling) {
                    self.leftScrolling = true;
                    !window.requestAnimationFrame ?
                        setTimeout(function() {
                            self.updateLeftScrolling();
                        }, 250) :
                        window.requestAnimationFrame(function() {
                            self.updateLeftScrolling();
                        });
                }
            });
            self.products.on("click", ".top-info", function() {
                var product = $(this).parents(".product");
                if (!self.filtering && product.hasClass("selected")) {
                    product.removeClass("selected");
                    self.selectedproductsNumber = self.selectedproductsNumber - 1;
                    self.upadteFilterBtn();
                } else if (!self.filtering && !product.hasClass("selected")) {
                    product.addClass("selected");
                    self.selectedproductsNumber = self.selectedproductsNumber + 1;
                    self.upadteFilterBtn();
                }
            });
            self.filterBtn.on("click", function(event) {
                event.preventDefault();
                if (self.filterActive) {
                    self.filtering = true;
                    self.showSelection();
                    self.filterActive = false;
                    self.filterBtn.removeClass("active");
                }
            });
            self.resetBtn.on("click", function(event) {
                event.preventDefault();
                if (self.filtering) {
                    self.filtering = false;
                    self.resetSelection();
                } else {
                    self.products.removeClass("selected");
                }
                self.selectedproductsNumber = 0;
                self.upadteFilterBtn();
            });
            this.navigation.on("click", "a", function(event) {
                event.preventDefault();
                self.updateSlider($(event.target).hasClass("next"));
            });
        };
        productsTable.prototype.upadteFilterBtn = function() {
            if (this.selectedproductsNumber >= 2) {
                this.filterActive = true;
                this.filterBtn.addClass("active");
            } else {
                this.filterActive = false;
                this.filterBtn.removeClass("active");
            }
        };
        productsTable.prototype.updateLeftScrolling = function() {
            var totalTableWidth = parseInt(this.tableColumns.eq(0).outerWidth(true)),
                tableViewport = parseInt(this.element.width()),
                scrollLeft = this.productsWrapper.scrollLeft();
            scrollLeft > 0 ?
                this.table.addClass("top-scrolling") :
                this.table.removeClass("top-scrolling");
            if (
                this.table.hasClass("top-fixed") &&
                (checkMQ() == "desktop" || checkMQ() == "mobile")
            ) {
                setTranformX(this.productsTopInfo, "-" + scrollLeft);
                setTranformX(this.featuresTopInfo, "0");
            }
            this.leftScrolling = false;
            this.updateNavigationVisibility(scrollLeft);
        };

        productsTable.prototype.updateNavigationVisibility = function(scrollLeft) {
            scrollLeft > 0 ?
                this.navigation.find(".prev").removeClass("inactive") :
                this.navigation.find(".prev").addClass("inactive");
            scrollLeft <
                this.tableColumns.outerWidth(true) - this.productsWrapper.width() &&
                this.tableColumns.outerWidth(true) > this.productsWrapper.width() ?
                this.navigation.find(".next").removeClass("inactive") :
                this.navigation.find(".next").addClass("inactive");
        };
        productsTable.prototype.updateTopScrolling = function(scrollTop) {
            var offsetTop = this.table.offset().top,
                tableScrollLeft = this.productsWrapper.scrollLeft();
            if (
                offsetTop <= scrollTop &&
                offsetTop + this.tableHeight - this.topInfoHeight >= scrollTop
            ) {
                if (!this.table.hasClass("top-fixed") &&
                    $(document).height() > offsetTop + $(window).height() + 200
                ) {
                    this.table.addClass("top-fixed").removeClass("top-scrolling");
                    this.productsTopInfo.css("top", "0");
                    this.navigation.find("a").css("top", "0px");
                    if (checkMQ() == "mobile") {
                        let lis = document.querySelectorAll(".deposit");
                        let li = document.querySelector(".deposit-guide");
                        for (var i = 0; i < lis.length; i++) {
                            if (this.table.hasClass("top-fixed")) {
                                lis[i].style.marginTop = 198 + "px";
                                li.style.marginTop = 198 + "px";
                            }
                        }
                    } else if (checkMQ() == "desktop") {
                        let lis = document.querySelectorAll(".deposit");
                        let li = document.querySelector(".deposit-guide");
                        for (var i = 0; i < lis.length; i++) {
                            if (this.table.hasClass("top-fixed")) {
                                lis[i].style.marginTop = 50 + "px";
                                li.style.marginTop = 50 + "px";
                            }
                        }
                    }
                }
            } else if (offsetTop <= scrollTop) {
                this.table.removeClass("top-fixed").removeClass("top-scrolling");
                if (checkMQ() == "desktop" || checkMQ() == "mobile") {
                    this.productsTopInfo.css(
                        "top",
                        this.tableHeight - this.topInfoHeight + "px"
                    );
                    this.navigation
                        .find("a")
                        .css("top", this.tableHeight - this.topInfoHeight + "px");
                }
            } else {
                this.table.removeClass("top-fixed top-scrolling");
                if (checkMQ() == "desktop" || checkMQ() == "mobile") {
                    this.productsTopInfo.attr("style", "");
                    this.navigation.find("a").attr("style", "");
                    let lis = document.querySelectorAll(".deposit");
                    let li = document.querySelector(".deposit-guide");
                    for (var i = 0; i < lis.length; i++) {
                        lis[i].style.marginTop = 0 + "px";
                        li.style.marginTop = 0 + "px";
                    }
                }
            }
            this.updateLeftScrolling();
        };
        productsTable.prototype.updateProperties = function() {
            this.tableHeight = this.table.height();
            this.productWidth = this.products.eq(0).width();
            this.topInfoHeight = this.featuresTopInfo.innerHeight() + 30;
            this.tableColumns.css(
                "width",
                this.productWidth * this.productsNumber + "px"
            );
        };
        productsTable.prototype.showSelection = function() {
            this.element.addClass("filtering");
            this.filterProducts();
        };
        productsTable.prototype.resetSelection = function() {
            this.tableColumns.css(
                "width",
                this.productWidth * this.productsNumber + "px"
            );
            this.element.removeClass("no-product-transition");
            this.resetProductsVisibility();
        };
        productsTable.prototype.filterProducts = function() {
            var self = this,
                containerOffsetLeft = self.tableColumns.offset().left,
                scrollLeft = self.productsWrapper.scrollLeft(),
                selectedProducts = this.products.filter(".selected"),
                numberProducts = selectedProducts.length;
            selectedProducts.each(function(index) {
                var product = $(this),
                    leftTranslate =
                    containerOffsetLeft +
                    index * self.productWidth +
                    scrollLeft -
                    product.offset().left;
                setTranformX(product, leftTranslate);
                if (index == numberProducts - 1) {
                    product.one(
                        "webkitTransitionEnd otransitionend oTransitionEnd msTransitionEnd transitionend",
                        function() {
                            setTimeout(function() {
                                self.element.addClass("no-product-transition");
                            }, 50);
                            setTimeout(function() {
                                self.element.addClass("filtered");
                                self.productsWrapper.scrollLeft(0);
                                self.tableColumns.css(
                                    "width",
                                    self.productWidth * numberProducts + "px"
                                );
                                selectedProducts.attr("style", "");
                                product.off(
                                    "webkitTransitionEnd otransitionend oTransitionEnd msTransitionEnd transitionend"
                                );
                                self.updateNavigationVisibility(0);
                            }, 100);
                        }
                    );
                }
            });
            if ($(".no-csstransitions").length > 0) {
                self.element.addClass("filtered");
                self.productsWrapper.scrollLeft(0);
                self.tableColumns.css("width", self.productWidth * numberProducts + "px");
                selectedProducts.attr("style", "");
                self.updateNavigationVisibility(0);
            }
        };
        productsTable.prototype.resetProductsVisibility = function() {
            var self = this,
                containerOffsetLeft = self.tableColumns.offset().left,
                selectedProducts = this.products.filter(".selected"),
                numberProducts = selectedProducts.length,
                scrollLeft = self.productsWrapper.scrollLeft(),
                n = 0;
            self.element.addClass("no-product-transition").removeClass("filtered");
            self.products.each(function(index) {
                var product = $(this);
                if (product.hasClass("selected")) {
                    n = n + 1;
                    var leftTranslate = (-index + n - 1) * self.productWidth;
                    setTranformX(product, leftTranslate);
                }
            });
            setTimeout(function() {
                self.element.removeClass("no-product-transition filtering");
                setTranformX(selectedProducts, "0");
                selectedProducts.removeClass("selected").attr("style", "");
            }, 50);
        };
        productsTable.prototype.updateSlider = function(bool) {
            var scrollLeft = this.productsWrapper.scrollLeft();
            scrollLeft = bool ?
                scrollLeft + this.productWidth :
                scrollLeft - this.productWidth;
            if (scrollLeft < 0) scrollLeft = 0;
            if (
                scrollLeft >
                this.tableColumns.outerWidth(true) - this.productsWrapper.width()
            )
                scrollLeft =
                this.tableColumns.outerWidth(true) - this.productsWrapper.width();
            this.productsWrapper.animate({
                    scrollLeft: scrollLeft,
                },
                200
            );
        };

        var comparisonTables = [];
        $(".cd-products-comparison-table").each(function() {
            comparisonTables.push(new productsTable($(this)));
        });
        $(window).on("load", function() {
            setFirstRowHeight();
            setDataHeight();
            setSuggestionsHeight();
        });
        var windowScrolling = false;
        $(window).on("scroll", function() {
            if (!windowScrolling) {
                windowScrolling = true;
                !window.requestAnimationFrame ?
                    setTimeout(checkScrolling, 250) :
                    window.requestAnimationFrame(checkScrolling);
            }
        });
        var windowResize = false;
        $(window).on("resize", function() {
            if (!windowResize) {
                windowResize = true;
                !window.requestAnimationFrame ?
                    setTimeout(checkResize, 250) :
                    window.requestAnimationFrame(checkResize);
                setFirstRowHeight();
                setDataHeight();
                setSuggestionsHeight();
            }
        });

        function checkScrolling() {
            var scrollTop = $(window).scrollTop();
            comparisonTables.forEach(function(element) {
                element.updateTopScrolling(scrollTop);
            });
            windowScrolling = false;
        }

        function checkResize() {
            comparisonTables.forEach(function(element) {
                element.updateProperties();
            });
            windowResize = false;
        }

        function checkMQ() {
            return window
                .getComputedStyle(comparisonTables[0].element.get(0), "::after")
                .getPropertyValue("content")
                .replace(/'/g, "")
                .replace(/"/g, "");
        }

        function setTranformX(element, value) {
            element.css({
                "-moz-transform": "translateX(" + value + "px)",
                "-webkit-transform": "translateX(" + value + "px)",
                "-ms-transform": "translateX(" + value + "px)",
                "-o-transform": "translateX(" + value + "px)",
                "	transform": "translateX(" + value + "px)",
            });
        }

        function setFirstRowHeight() {
            var biggestHeight = 0,
                dataContainers = document.querySelectorAll(".deposit"),
                dataHeight = document.querySelector(".deposit-guide");
            dataContainers.forEach(function(element, index) {
                biggestHeight =
                    element.offsetHeight > biggestHeight ?
                    element.offsetHeight :
                    biggestHeight;
            });
            dataHeight.style.height = biggestHeight + "px";
            for (var i = 0; i < dataContainers.length; i++) {
                if (dataContainers[i].clientHeight < biggestHeight) {
                    dataContainers[i].style.height = biggestHeight + "px";
                }
            }
        }

        function setDataHeight() {
            var biggestHeight = 0,
                dataContainers = document.querySelectorAll(
                    ".product .cd-features-list .fees-guide"
                ),
                dataHeight = document.querySelector(".fees");
            dataContainers.forEach(function(element, index) {
                biggestHeight =
                    element.offsetHeight > biggestHeight ?
                    element.offsetHeight :
                    biggestHeight;
            });
            dataHeight.style.height = biggestHeight + "px";
            for (var i = 0; i < dataContainers.length; i++) {
                if (dataContainers[i].clientHeight < biggestHeight) {
                    dataContainers[i].style.height = biggestHeight + "px";
                }
            }
        }

        function setSuggestionsHeight() {
            var biggestHeight = 0,
                dataContainers = document.querySelectorAll(
                    ".product .cd-features-list > li:last-child"
                ),
                dataHeight = document.querySelector(".suggestions");
            dataContainers.forEach(function(element, index) {
                biggestHeight =
                    element.offsetHeight > biggestHeight ?
                    element.offsetHeight :
                    biggestHeight;
            });
            dataHeight.style.height = biggestHeight + "px";
            for (var i = 0; i < dataContainers.length; i++) {
                if (dataContainers[i].clientHeight < biggestHeight) {
                    dataContainers[i].style.height = biggestHeight + "px";
                }
            }
        }
    }
});

$(document).ready(function() {
    const Alerts = document.querySelectorAll('.tru-banner-alert');
    const AlertHeadings = document.querySelectorAll(".tru-banner-alert .card .card-header .btn");
    const AlertTriggers = document.querySelectorAll(".tru-banner-alert .card .card-header .btn");
    const AlertContent = document.querySelectorAll(".tru-banner-alert .card .alert-card-content");
    const AlertClose = document.querySelectorAll(".tru-banner-alert .button.close")
    if (Alerts.length === 0) {
        return;
    } else {
        readCookie();
        for (n = 0; n < Alerts.length; n++) {
            Alerts[n].setAttribute("id", "alert-" + n);
            AlertHeadings[n].setAttribute("id", "alert-heading-" + n);
            AlertTriggers[n].setAttribute("aria-controls", "alert-collapse-" + n),
                AlertContent[n].setAttribute("id", "alert-collapse-" + n)
            AlertContent[n].setAttribute("aria-labelledby", "alert-heading-" + n),
                AlertTriggers[n].dataset.target = "#alert-collapse-" + n
            AlertContent[n].dataset.parent = "#alert-" + n
        }

        $(AlertTriggers).on("click", function() {
            $(this).closest(".tru-banner-alert").find(".carat").toggleClass("carat-down");
        });

        $(AlertClose).click(function() {
            setCookie();
        });
    }
});

function setCookie() {
    let alertCookie = $('.globalalertv2 div').first().attr('id');
    document.cookie = "alert =" + alertCookie + ";";
}

function getCookie(alert) {
    let name = alert + "=";
    let spli = document.cookie.split(';');
    for (var j = 0; j < spli.length; j++) {
        let char = spli[j];
        while (char.charAt(0) == ' ') {
            char = char.substring(1);
        }
        if (char.indexOf(name) == 0) {
            return char.substring(name.length, char.length);
        }
    }
    return "";
}

function readCookie() {
    let cookie = getCookie("alert");
    if (cookie == "") {
        return;
    } else {
        $('#' + cookie).css('display', 'none');
    }
}

'use strict';
window.heroTwoComponent = function() {
    'use strict';

    var SEL = {
        hero: '.herov2',
        heroImageComp: '.heroImageComp',
        creditCard: '.truist-hero--image-credcard',
        modalTrigger: '.herov2 a.modalWindowTrigger',
        truistHero: '.truist-hero',
        contentImage: '.image-content-holder',
        heroBgImage: '.hero-banner-bg-image'
    };

    var qs = function(sel, ctx) {
        return (ctx || document).querySelector(sel);
    };
    var qsa = function(sel, ctx) {
        return Array.prototype.slice.call((ctx || document).querySelectorAll(sel));
    };

    var getBS5 = function() {
        return window.__bootstrap5__;
    };

    var _private = {

        init: function(heroV2ComponentEl) {
            if (!heroV2ComponentEl || !(heroV2ComponentEl instanceof Element)) {
                return;
            }
            try {
                _private.initLightstream(heroV2ComponentEl);

                var bs5 = getBS5();
                if (bs5) {
                    _private.initBS5Features(bs5);
                } else {
                    document.addEventListener('bootstrap5:ready', function(event) {
                        _private.initBS5Features(event.detail || getBS5());
                    });
                }
            } catch (e) {
                console.error('Hero V2 Component: init error: ' + (e && (e.message || String(e)) ? (e.message || String(e)) : 'unknown error'));
            }
        },


        initLightstream: function(el) {
            try {
                var lightStreamEnabled = el.getAttribute('data-lightstream') || '';
                if (lightStreamEnabled && typeof CommonUtils !== 'undefined') {
                    CommonUtils.initPlaceholderLinks(el);
                    var lightStreamPurpose = el.getAttribute('data-loanpurpose') || '';
                    if (typeof lsiRatesLoadWait === 'function') {
                        lsiRatesLoadWait(
                            function() {
                                return lsiEnabled === true;
                            },
                            function() {
                                lsiRetriveRateRanges(lightStreamPurpose, $(el), false, false, '.herov2-lsc-loader');
                            }
                        );
                    }
                }
            } catch (e) {
                if (window.Logger && typeof window.Logger.error === 'function') {
                    window.Logger.error('Hero V2 Component: Error with lightstream data process: ' + (e && (e.message || String(e)) ? (e.message || String(e)) : 'unknown error'));
                } else {
                    console.error('Hero V2 Component: Error with lightstream data process: ' + (e && (e.message || String(e)) ? (e.message || String(e)) : 'unknown error'));
                }
            }
        },


        initBS5Features: function(bs5) {
            if (!qsa(SEL.hero).length) {
                return;
            }
            try {
                _private.initCreditCardImage();
                _private.initModalTriggers(bs5);
                _private.initImageDisplay();
            } catch (e) {
                console.error('Hero V2 Component: BS5 init error: ' + (e && (e.message || String(e)) ? (e.message || String(e)) : 'unknown error'));
            }
        },


        initCreditCardImage: function() {
            var creditCardImg = qs(SEL.creditCard);
            if (creditCardImg && !creditCardImg.getAttribute('src')) {
                creditCardImg.parentNode.removeChild(creditCardImg);
            }
        },


        initModalTriggers: function(bs5) {
            qsa(SEL.modalTrigger).forEach(function(el) {
                el.setAttribute('role', 'button');
                el.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter' || e.key === ' ' || e.keyCode === 13 || e.keyCode === 32) {
                        e.preventDefault();
                        var targetId = el.getAttribute('data-bs-target') || '';
                        if (/^#[a-zA-Z0-9_-]+$/.test(targetId)) {
                            var modalEl = qs(targetId);
                            if (modalEl && bs5 && bs5.Modal) {
                                bs5.Modal.getOrCreateInstance(modalEl).toggle();
                            }
                        }
                    }
                });
            });
        },

        initImageDisplay: function() {
            window.addEventListener('load', function() {

                qsa(SEL.heroImageComp).forEach(function(heroComp) {
                    var mobileScreenImage = (heroComp.getAttribute('data-mobilebgcolor') || '').replace(/[^a-zA-Z0-9_-]/g, '');
                    var mobileBgEl = mobileScreenImage ? qs('.mobileBg-' + mobileScreenImage) : null;
                    if (mobileBgEl) {
                        mobileBgEl.classList.add('removeHeroBg');
                    }
                });


                var truistHero = qs(SEL.truistHero);
                var contentImage = qs(SEL.contentImage);
                if (truistHero && contentImage && truistHero.classList.contains('truist-hero--image')) {
                    var nodes = Array.prototype.slice.call(contentImage.childNodes);
                    if (typeof truistHero.replaceChildren === 'function') {
                        truistHero.replaceChildren.apply(truistHero, nodes);
                    } else {

                        while (truistHero.firstChild) {
                            truistHero.removeChild(truistHero.firstChild);
                        }
                        nodes.forEach(function(node) {
                            truistHero.appendChild(node);
                        });
                    }
                }


                var heroBgImage = qs(SEL.heroBgImage);
                if (heroBgImage) {
                    var truistHeroEl = heroBgImage.closest(SEL.truistHero);
                    if (truistHeroEl && !Array.prototype.some.call(truistHeroEl.classList, function(c) {
                            return c.indexOf('mobileBg-') === 0;
                        })) {
                        heroBgImage.classList.add('herov2-bg-hidden');
                    }
                }
            });
        }

    };

    return {
        init: _private.init
    };
};


(() => {
    const $itemSlider = $(".item-slider");

    if ($itemSlider.length) {
        document.addEventListener("DOMContentLoaded", async () => {
            try {
                await LibLoader.get({
                    uri: '/etc/clientlibs/truist-global/clientlibs/js/splide.js',
                    verifier: () => !!Splide
                }, '/etc/clientlibs/truist-global/clientlibs/css/splide.css');
            } catch (err) {
                // CWE-117 (SEC-CWE117-S03): use sanitizing Logger; fall back to no-op.
                if (typeof window !== 'undefined' && window.Logger && typeof window.Logger.error === 'function') {
                    window.Logger.error('item-slider error', err && err.message);
                }
            }

            const itemSliders = document.querySelectorAll(".item-slider");

            for (i = 0; i < itemSliders.length; i++) {
                const fadeOutLoader = () => {
                    $('.item-slider-section .loading-container').fadeOut('slow');
                    $(itemSliders[i]).fadeIn('slow');
                };

                const tabControl = () => {
                    $($itemSlider).find('.item-slider-card-link').attr({
                        "aria-hidden": "true",
                        tabindex: "-1"
                    });
                    if ($($itemSlider).find('.splide__slide').hasClass("is-visible") || $($itemSlider).find('.splide__slide').attr('aria-hidden' === false)) {
                        let $this = $($itemSlider).find('.splide__slide[aria-hidden="false"]');
                        let itemHidden = $($itemSlider).find('.splide__slide[aria-hidden="true"]');
                        $($this).find('.item-slider-card-link').attr({
                            "aria-hidden": "false",
                            tabindex: "0"
                        });
                        $($this).attr({
                            "aria-hidden": "false",
                            tabindex: "0"
                        });
                        itemHidden.attr({
                            "aria-hidden": "true",
                            tabindex: "-1"
                        })
                    } else if (!$($itemSlider).find('.splide__slide').hasClass("is-visible")) {
                        let $this = $($itemSlider).find('.splide__slide:not(".is-visible")');
                        $($this).find('.item-slider-card-link').attr({
                            "aria-hidden": "true",
                            tabindex: "-1"
                        });
                    }
                };

                const keyBoardControls = () => {
                    $($itemSlider).keydown(function(e) {
                        var arrow = {
                            left: 37,
                            right: 39
                        };
                        switch (e.which) {
                            case arrow.left:
                                $(this).find('.splide__slide.is-active a').blur().parent().prev().addClass('is-active').find('a').focus()
                                break;
                            case arrow.right:
                                $(this).find('.splide__slide.is-active a').blur().parent().next().addClass('focused').find('a').focus()
                                break;
                            default:
                                return;
                        }
                    });
                };


                const arrowReadOutADA = (direction) => {
                    $('.item-slider-' + direction).click(function() {
                        $('.splide__slide.is-active').attr("aria-live", "polite");
                        setTimeout(function() {
                            $('.splide__slide.is-active').removeAttr("aria-live");
                        }, 500);
                    });
                };

                const getNativeItemIndex = (slider) => {
                    var items = $(slider).find(".splide__slide");
                    for (var j = 0; j < items.length; j++) {
                        var sliderItem = items[j];
                        if ('itemnative' in sliderItem.dataset) {
                            return j;
                        }
                    }
                    return 0;
                }

                var startIndex = getNativeItemIndex(itemSliders[i]);
                new Splide(itemSliders[i], {
                    type: "slide",
                    rewind: false,
                    speed: 300,
                    perMove: 1,
                    perPage: 1,
                    arrows: true,
                    gap: 8,
                    classes: {
                        prev: "item-slider-before",
                        next: "item-slider-after",
                    },
                    pagination: false,
                    autoplay: false,
                    hasProgress: false,
                    easing: "ease-in-out",
                    accessibility: true,
                    keyboard: true,
                    drag: true,
                    dragAngleThreshold: 100,
                    swipeDistanceThreshold: 0.5,
                    flickPower: 100,
                    flickMaxPages: 0,
                    direction: "ltr",
                    cover: false,
                    trimSpace: true,
                    fixedWidth: 155,
                    autoHeight: true,
                    resetProgress: false,
                    start: startIndex,
                    slideFocus: false,
                    updateOnMove: true
                }).mount().on('moved', tabControl);
                tabControl();
                keyBoardControls();
                fadeOutLoader();
                arrowReadOutADA('before');
                arrowReadOutADA('after');
            }
        });
    }
})();
'use strict';

// Life Force interactive calculator functionality
$(() => $('#lf-calculator').each((i, elem) => {
    const $CMP = $(elem);
    const CMP_DATA = $CMP.data();
    if (!CMP_DATA.jsonUrl) {
        return;
    } // bail out if url is blank, since .getJSON() call below with blank url would request the page again!

    let arrData = [];
    let lf_responseCont = "";
    let item, key;

    // Fill the first dropdown with data.
    $.getJSON(CMP_DATA.jsonUrl, data => {
        let medicalPlanOptions = [];

        $.each(data, function(index, value) {
            medicalPlanOptions.push(value.Medical_plan);
            arrData = data;
        });

        // Remove duplicates. We want unique Medical Plans.
        medicalPlanOptions = Array.from(new Set(medicalPlanOptions));

        // Fill the first dropdown with unique Medical Plans.
        $.each(medicalPlanOptions, function(index, value) {
            $('#Medical_plan').append('<option value="' + value + '">' + value + '</option>');
        });

        /* Initial Load of Coverage Level options */
        generate_coverageLvlOpts();

        /* Initial Load of Salary Range options */
        generate_salaryRangOpts();
    });

    $('#Medical_plan').change(function() {
        $('#Medical_plan').parent().removeClass('lf-calculator-floating-select-error');
        $(this).parent().next('.mandatoryFld_error').addClass('hidden');

        $('#Coverage_level').attr('value', "");
        $('#Salary_range').attr('value', "");
        $('#Salary_range').empty()
            .append('<option value="" style=" display:none;" aria-hidden="true"></option>');
        generate_coverageLvlOpts();

    });

    function generate_coverageLvlOpts() {
        var Medical_plan = $('#Medical_plan').attr('value').trim();

        var coverageLevelOptions = [];

        var filterData = arrData.filter(function(value) {
            return Medical_plan === Medical_plan;
        });

        $.each(filterData, function(index, value) {
            coverageLevelOptions.push(value.Coverage_level);
        });

        coverageLevelOptions = Array.from(new Set(coverageLevelOptions));

        $('#Coverage_level')
            .empty()
            .append('<option value="" style=" display:none;" aria-hidden="true"></option>');

        $.each(coverageLevelOptions, function(index, value) {
            // Now, fill the second dropdown list with coverage level.
            $('#Coverage_level').append('<option value="' + value + '">' + value + '</option>');
        });
    }

    $('#Coverage_level').change(function() {
        $('#Coverage_level').parent().removeClass('lf-calculator-floating-select-error');
        $(this).parent().next('.mandatoryFld_error').addClass('hidden');

        $('#Salary_range').attr('value', "");
        generate_salaryRangOpts();
    });

    function generate_salaryRangOpts() {
        let Coverage_level = $('#Coverage_level').attr('value').trim();
        let salaryRangeOptions = [];

        let filterData2 = arrData.filter(function(value) {
            return Coverage_level === Coverage_level;
        });

        // Reset Coverage Level drop-down value

        $.each(filterData2, function(index, value) {
            salaryRangeOptions.push(value.Salary_range);
        });

        salaryRangeOptions = Array.from(new Set(salaryRangeOptions));

        $('#Salary_range')
            .empty()
            .append('<option value="" style=" display:none;" aria-hidden="true"></option>');

        $.each(salaryRangeOptions, function(index, value) {
            // Now, fill the third dropdown list with salary range.
            $('#Salary_range').append('<option value="' + value + '">' + value + '</option>');
        });
    }

    $('#Salary_range').change(function() {
        $('#Salary_range').parent().removeClass('lf-calculator-floating-select-error');
        $(this).parent().next('.mandatoryFld_error').addClass('hidden');
    });

    //Manipulate filtered results from JSON
    function fetchResultItem(medicalPlan, coverageLvl, salaryRng) {
        for (item of arrData) {

            if (item["Medical_plan"] == medicalPlan && item["Coverage_level"] == coverageLvl && item["Salary_range"] == salaryRng) {
                //Render the results based on the filtered array object
                let filteredArr = [];
                lf_responseCont = "";

                for (key in item) {
                    filteredArr.push(key);
                }

                let FilteredPhaseLen = (parseInt(filteredArr.length) - 3) / 3;
                lf_responseCont = '<h2 class="sr-only">Life force calculator results, ' + FilteredPhaseLen + ' resources</h2>';
                for (var i = 0; i < FilteredPhaseLen; i++) {
                    lf_responseCont += '<div class="lf-resultSec">';
                    lf_responseCont += '<div class="lt-resultHeadSec">';
                    if (CMP_DATA.phaseLink) {
                        lf_responseCont += '<h3 class="lt-resultHeadTxt">Phase ' + (i + 2) + '</h3> <a href="#" class="lt-resultHeadLnkTxt lf-seeDetailModal-phase' + (i + 2) + '" data-toggle="modal">' + CMP_DATA.phaseLink + '</a>';
                        lf_responseCont += '<span class="sr-only">' + CMP_DATA.phaseSrContent + '</span>';
                    } else {
                        lf_responseCont += '<h3 class="lt-resultHeadTxt">Phase ' + (i + 2) + '</h3>';
                    }
                    lf_responseCont += '</div>';
                    lf_responseCont += '<div class="lf-resultPayOptSec">';
                    lf_responseCont += '<div class="lf-resultPayOpt"><span class="lf-resultPayOptLbl">Semi-monthly: </span>';
                    lf_responseCont += '<span class="lf-resultPayOptVal">' + item["Semi_monthly_phase_" + (i + 2)] + '</span></div>';
                    lf_responseCont += '<div class="lf-resultPayOpt"><span class="lf-resultPayOptLbl">Monthly: </span>';
                    lf_responseCont += '<span class="lf-resultPayOptVal">' + item["Monthly_phase_" + (i + 2)] + '</span></div>';
                    lf_responseCont += '<div class="lf-resultPayOpt"><span class="lf-resultPayOptLbl">Annual: </span>';
                    lf_responseCont += '<span class="lf-resultPayOptVal">' + item["Annual_phase_" + (i + 2)] + '</span></div>';
                    lf_responseCont += '</div>';
                    lf_responseCont += '</div>';
                }
            } else {
                $('#lf-responseSec').empty();
            }

        }
        // Modal window for result section "see details" link
        setTimeout(function() {
            $(document).on('click', '.lt-resultHeadLnkTxt', function() {
                //console.log($(this).parent().parent().find('lf-seeDetailModal'));
                var seeDetailClassNm = this.className.split('');
                var getPhaseID = seeDetailClassNm[seeDetailClassNm.length - 1];
                $('.lf-seeDetailModalPh' + getPhaseID).modal('show');
            });

            $('.lf-seeDetailModalClose').on('click', function() {
                $('.lf-seeDetailModal').modal('hide');
            });
        }, 1000);

    }

    //Calculate button click event
    $('.lf-calculate-btn').on('click', function(e) {
        e.preventDefault();
        let selectedMedPlan = $('#Medical_plan').val();
        let selectedCoverageLvl = $('#Coverage_level').val();
        let selectedSalaryRng = $('#Salary_range').val();

        if ($('.lf-calculator-floating-label').hasClass('lf-calculator-floating-select-error')) {
            $(this).siblings('.mandatoryFld_error').toggleClass('hidden');
        }

        if (selectedMedPlan == "" || selectedMedPlan == null) {
            $('.mandatoryFld_error').removeClass('hidden');
            $('#Medical_plan').parent().addClass('lf-calculator-floating-select-error');
            $('#Coverage_level').parent().addClass('lf-calculator-floating-select-error');
            $('#Salary_range').parent().addClass('lf-calculator-floating-select-error');
            return false;
        } else if (selectedCoverageLvl == "" || selectedCoverageLvl == null) {
            $('#Coverage_level').parent().addClass('lf-calculator-floating-select-error');
            $('#Coverage_level').parent().siblings('.mandatoryFld_error').removeClass('hidden');
            $('#Salary_range').parent().addClass('lf-calculator-floating-select-error');
            $('#Salary_range').parent().siblings('.mandatoryFld_error').removeClass('hidden');
            return false;
        } else if (selectedSalaryRng == "" || selectedSalaryRng == null) {
            $('#Salary_range').parent().addClass('lf-calculator-floating-select-error');
            $('#Salary_range').parent().siblings('.mandatoryFld_error').removeClass('hidden');
            return false;
        } else {
            $('.mandatoryFld_error').addClass('hidden');
            fetchResultItem(selectedMedPlan, selectedCoverageLvl, selectedSalaryRng);
            $('#lf-responseSec').empty().append(lf_responseCont);

            //Analytics implementations
            var cData = new Object();
            cData.events = "event39";
            cData.toolFlowName = "truist|benefits|lifeforce_benefits_calculator"
            cData.toolFlowInfo = "medicalplan:" + selectedMedPlan.trim().replace(/[^a-z0-9\s]/gi, '').replace(/[_\s]/g, '_').toLowerCase() + ",coveragelevel:" + selectedCoverageLvl.trim().replace(/[^a-z0-9\s]/gi, '').replace(/[_\s]/g, '_').toLowerCase() + ",salaryrange:" + selectedSalaryRng.replace(/[^a-z0-9\s]/gi, '').trim().replace(/[_\s]+/g, '_').toLowerCase();
            marTech.trackAction(cData);
        }

    });

    //Reset click event
    $('.lf-reset').on('click', function(e) {
        e.preventDefault();
        $('.mandatoryFld_error').addClass('hidden');
        $('.lf-calculator-floating-label').removeClass('lf-calculator-floating-select-error')
        $('#lf-responseSec').empty();
        $('.lf-calculator-floating-select').val('').attr('value', '');
        $('#Coverage_level').empty();
        $('#Salary_range').empty();
    });

    init_lfCalculator();

    function init_lfCalculator(item) {
        fetchResultItem("BCBSNC PPO $500", "Teammate only", "≤ $49,999");
        setTimeout(function() {
            //Select the first option by default
            $("#Medical_plan").val($("#Medical_plan option:eq(1)").val());
            $("#Coverage_level").val($("#Coverage_level option:eq(1)").val());
            $("#Coverage_level").trigger('click');
            $("#Salary_range").val($("#Salary_range option:eq(1)").val());
            var selected_MedPlan = $("#Medical_plan").find(":selected").val();
            var selected_CoverageLvl = $("#Coverage_level").find(":selected").val();
            var selected_SalRange = $("#Salary_range").find(":selected").val();
            $("#Medical_plan").attr('value', selected_MedPlan);
            $("#Coverage_level").attr('value', selected_CoverageLvl);
            $("#Salary_range").attr('value', selected_SalRange);
            $('.lf-calculate-btn').trigger('click');
        }, 100);
    }
}));

(() => {
    const CMP_TRU_GRID = $(".truist-gridContainer");
    if (CMP_TRU_GRID.length === 0) {
        return;
    } else {
        $(".loading-container").css("display", "flex");

        const constructGrid = () => {
            const TRU_GRIDS = document.querySelectorAll(".truist-gridContainer");
            TRU_GRIDS.forEach((grid) => {
                $(grid).css("min-height", "375px").attr("aria-busy", "true");
                // *** The GRID_***** array order MUST NOT be altered
                // without updating the indices in the functions ***//
                const GRID_VARIANT = [
                        "tru-grid-25-1", // 0
                        "tru-grid-33-1", // 1
                        "tru-grid-50-50-1", // 2
                        "tru-grid-40-60-1", // 3
                        "tru-grid-25-75-1", // 4
                        "tru-grid-50-50-2", // 5
                        "tru-grid-40-60-2", // 6
                        "tru-grid-25-75-2", // 7
                        "tru-grid-25-25-50-1", // 8
                        "tru-grid-25-50-25-1", // 9
                        "tru-grid-50-50-3", // 10
                        "tru-grid-40-60-3", // 11
                        "tru-grid-25-75-3", // 12
                        "tru-grid-100-1", // 13
                    ],
                    GRID_CLASS = [
                        "col-lg-3", // 0
                        "col-lg-4", // 1
                        "col-lg-5", // 2
                        "col-lg-6", // 3
                        "col-lg-7", // 4
                        "col-lg-9", // 5
                        "col-sm-12", // 6
                        "col-sm-4", // 7
                        "col-sm-3", // 8
                    ],
                    GRID_UTILITY = [
                        "order-3", // 0
                        "order-2", // 1
                        "order-1", // 2
                        "flip", // 3
                        "separate", // 4
                    ],
                    TILE = $(grid).find(".tile"),
                    WRAP = $(TILE).find(".component-wrapper"),
                    INNER_ROW = $(TILE).find(".row");
                $(TILE).css("visibility", "hidden");
                const indexRange = (arr, start, end) => {
                    return arr.slice(start, end);
                };

                $(CMP_TRU_GRID)
                    .find(TILE)
                    .show()
                    .removeClass(indexRange(GRID_CLASS, 0, 9))
                    .find(WRAP)
                    .show()
                    .siblings(INNER_ROW)
                    .show();
                if ($(grid).hasClass(GRID_VARIANT[0])) {
                    $(grid).find(TILE).addClass(GRID_CLASS[0]).find(INNER_ROW).hide();
                } else if ($(grid).hasClass(GRID_VARIANT[1])) {
                    $(grid).find(TILE).addClass(GRID_CLASS[1]).last().hide();
                    $(grid).find(TILE).find(INNER_ROW).hide();
                } else if (
                    $(grid).hasClass(GRID_VARIANT[2]) ||
                    $(grid).hasClass(GRID_VARIANT[5])
                ) {
                    $(grid).find(TILE).addClass(GRID_CLASS[3]).find(INNER_ROW).hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE).last().hide();
                } else if (
                    $(grid).hasClass(GRID_VARIANT[3]) ||
                    $(grid).hasClass(GRID_VARIANT[6])
                ) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[2]).find(INNER_ROW).hide();
                    $(grid).find(TILE[1]).addClass(GRID_CLASS[4]).find(INNER_ROW).hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE).last().hide();
                } else if (
                    $(grid).hasClass(GRID_VARIANT[4]) ||
                    $(grid).hasClass(GRID_VARIANT[7])
                ) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[0]).find(INNER_ROW).hide();
                    $(grid).find(TILE[1]).addClass(GRID_CLASS[5]).find(INNER_ROW).hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE).last().hide();
                } else if ($(grid).hasClass(GRID_VARIANT[8])) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[0]).find(INNER_ROW).hide();
                    $(grid).find(TILE[1]).addClass(GRID_CLASS[0]).find(INNER_ROW).hide();
                    $(grid).find(TILE[2]).addClass(GRID_CLASS[3]);
                    $(grid).find(TILE).last().hide();
                } else if ($(grid).hasClass(GRID_VARIANT[9])) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[0]).find(INNER_ROW).hide();
                    $(grid).find(TILE[1]).addClass(GRID_CLASS[3]).find(INNER_ROW).hide();
                    $(grid).find(TILE[2]).addClass(GRID_CLASS[0]);
                    $(grid).find(TILE).last().hide();
                } else if ($(grid).hasClass(GRID_VARIANT[10])) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[3]).find(INNER_ROW).hide();
                    $(grid)
                        .find(TILE[1])
                        .addClass(GRID_CLASS[3])
                        .find(WRAP)
                        .first()
                        .hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE[3]).last().hide();
                } else if ($(grid).hasClass(GRID_VARIANT[11])) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[4]).find(INNER_ROW).hide();
                    $(grid)
                        .find(TILE[1])
                        .addClass(GRID_CLASS[2])
                        .find(WRAP)
                        .first()
                        .hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE[3]).last().hide();
                } else if ($(grid).hasClass(GRID_VARIANT[12])) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[5]).find(INNER_ROW).hide();
                    $(grid)
                        .find(TILE[1])
                        .addClass(GRID_CLASS[0])
                        .find(WRAP)
                        .first()
                        .hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE[3]).last().hide();
                } else if ($(grid).hasClass(GRID_VARIANT[13])) {
                    $(grid).find(TILE[0]).addClass(GRID_CLASS[6]).find(INNER_ROW).hide();
                    $(grid).find(TILE[1]).hide();
                    $(grid).find(TILE[2]).hide();
                    $(grid).find(TILE[3]).hide();
                }

                if ($(grid).hasClass(GRID_UTILITY[3])) {
                    if ($(grid).hasClass(indexRange(GRID_VARIANT, 8, 11))) {
                        $(grid).find(TILE[0]).addClass(GRID_UTILITY[0]);
                        $(grid).find(TILE[1]).addClass(GRID_UTILITY[1]);
                        $(grid).find(TILE[2]).addClass(GRID_UTILITY[2]);
                    } else {
                        $(grid).find(TILE[0]).addClass(GRID_UTILITY[1]);
                        $(grid).find(TILE[1]).addClass(GRID_UTILITY[2]);
                    }
                }

                if ($(grid).hasClass(GRID_VARIANT[5])) {
                    $(grid).find(TILE[0]).find(WRAP).first().hide();
                    $(grid).find(TILE[0]).find(INNER_ROW).show();
                }

                if (
                    $(grid).hasClass(GRID_VARIANT[6]) ||
                    $(grid).hasClass(GRID_VARIANT[7])
                ) {
                    $(grid).find(TILE[0]).find(WRAP).first().hide();
                    $(grid).find(TILE[0]).find(INNER_ROW).show();
                }

                let maxHeight = 0;
                let helperDivs = [];

                $(grid)
                    .find(TILE)
                    .filter(":visible")
                    .each(function() {
                        const helperElements = $(this).find(
                            ".component-wrapper div[data-component-helper]:not(.staticcardv2)"
                        );
                        if (helperElements.length > 0) {
                            helperElements.each(function() {
                                helperDivs.push(this);

                                const elementHeight = $(this).outerHeight();

                                if (elementHeight > maxHeight) {
                                    maxHeight = elementHeight;
                                }
                            });
                        }
                    });

                if (maxHeight > 0 && helperDivs.length > 0) {
                    $(helperDivs).css("height", maxHeight + "px");
                }
                $(".loading-container").css("display", "none");
                setTimeout(function() {
                    $(TRU_GRIDS).css("max-height", "auto").attr("aria-busy", "false");
                    $(TILE).css("visibility", "visible");
                }, 500);
            });
        };

        $(window).on("load resize", constructGrid);
    }
})();


(() => {
    const CMP_SKINNY_BANNER = $(".skinny-banner");
    if (CMP_SKINNY_BANNER.length === 0) {
        return;
    } else {
        const SKINNY_BANNERS = document.querySelectorAll('.skinny-banner');
        SKINNY_BANNERS.forEach(banner => {
            // *** Array item order MUST NOT be altered without updating the indices in the functions ***//
            BANNER_UTILITY = [
                'order-3', //0
                'order-2', //1
                'order-1', //2
                'flip', //3
                'text-center', //4
                'half-width-left', //5
                'half-width-center', //6
                'half-width-right' //7
            ], BG_CLASS = [
                'bg-clear', //0
                'bg-ntrl-white', //1
                'bg-off-white', //2
                'bg-mist', //3
                'bg-mist-dk', //4
                'bg-sky-blue-ltr', //5
                'bg-sky-blue-lt', //6
                'bg-ntrl-gray', //7
                'bg-dusk-dkr', //8
                'bg-tru-ppl' //9
            ], TILE = $(banner).children();
            const indexRange = (arr, start, end) => {
                return arr.slice(start, end)
            };
            if ($(banner).parent().hasClass('aem-GridColumn--default--12')) {
                $(banner).parent().css('width', '100%');
            }
            if ($(banner).hasClass(BANNER_UTILITY[5])) {
                $(banner).parent().addClass('d-flex justify-content-start');
            } else if ($(banner).hasClass(BANNER_UTILITY[6])) {
                $(banner).parent().addClass('d-flex justify-content-center');
            } else if ($(banner).hasClass(BANNER_UTILITY[7])) {
                $(banner).parent().addClass('d-flex justify-content-end');
            } else if ($(banner).hasClass('full-width')) {
                $(banner).removeClass(indexRange(BANNER_UTILITY, 5, 8))
            }
            if ($(banner).hasClass('flip')) {
                $(banner).find(TILE[0]).addClass(BANNER_UTILITY[0]);
                $(banner).find(TILE[1]).addClass(BANNER_UTILITY[1]);
                $(banner).find(TILE[2]).addClass(BANNER_UTILITY[2]);
            }
        });
    }
})();

