        addCardCTA: function addCardCTA() {

            var DAM_THUMB_BASE = '/content/dam/truist-bank/us/en/images/article/perspectives/legacy-thumbnails/';
            var DEFAULT_THUMBNAILS = {
                'Article': DAM_THUMB_BASE + 'perspectives-default-article.svg',
                'Podcast': DAM_THUMB_BASE + 'perspectives-default-podcast.svg',
                'Video': DAM_THUMB_BASE + 'perspectives-default-video.svg',
                'Infographic': DAM_THUMB_BASE + 'perspectives-default-infographic.svg'
            };
            var DEFAULT_THUMBNAIL_FALLBACK = DAM_THUMB_BASE + 'perspectives-default-article.svg';


            var MEDIA_TYPE_MAP = {
                'Article': {
                    cta: 'Read Article',
                    icon: 'mediatype-article-icon'
                },
                'Podcast': {
                    cta: 'Listen to Podcast',
                    icon: 'mediatype-podcast-icon'
                },
                'Video': {
                    cta: 'Watch Video',
                    icon: 'mediatype-video-icon'
                },
                'Calculator': {
                    cta: 'View Calculator',
                    icon: 'mediatype-calculator-icon'
                },
                'Press release': {
                    cta: 'View Press Release',
                    icon: 'mediatype-article-icon'
                },
                'Whitepaper': {
                    cta: 'View Whitepaper',
                    icon: 'mediatype-article-icon'
                },
                'Infographic': {
                    cta: 'View Infographic',
                    icon: 'mediatype-article-icon'
                }
            };

            var cardCTAurls = $('.featured-article-list .item');

            cardCTAurls.each(function() {
                var ctahref = $(this).attr("data-href");
                var cardmedia = $(this).find('.dy-card-media-type').text();
                var cardbody = $(this).find('.card-body');
                var mediaInfo = MEDIA_TYPE_MAP[cardmedia];

                if (mediaInfo) {
                    var cardTitle = $(this).find('.item-description h3').text();
                    var $srOnly = $('<span>').addClass('sr-only').text(' about ' + cardTitle + '.');
                    var $anchor = $('<a>')
                        .attr('href', isSafeUrl(ctahref) ? ctahref : '#')
                        .attr('target', '_self')
                        .addClass('gl-align-center card-cta-onkey')
                        .attr('data-wa-track-clk', '1')
                        .attr('data-wa-linkname', 'Read article')
                        .attr('data-wa-linktype', 'navigation')
                        .attr('data-wa-linkurl', '#')
                        .text(mediaInfo.cta)
                        .append($srOnly);
                    var $innerDiv = $('<div>')
                        .addClass('author-cta-styling global-cta-btn gl-align-left')
                        .attr('data-wa-component', 'CTA')
                        .append($anchor);
                    var $outerDiv = $('<div>')
                        .addClass('featured-cta cta button cta__color--ghost-light cta__display--inline')
                        .append($innerDiv);
                    cardbody.append($outerDiv);
                    $(this).find('.dy-card-media-type').addClass(mediaInfo.icon);
                }

                // Add default thumbnail if no image defined for card
                var cardimg = $(this).find('.list-group-image');
                var cardimgurl = cardimg.attr('src');
                if (cardimgurl != null && cardimgurl.replace(/\s/g, '') === '') {
                    cardimg.attr('src', DEFAULT_THUMBNAILS[cardmedia] || DEFAULT_THUMBNAIL_FALLBACK);
                }
            });

            $('.card-cta-onkey').on('keydown', function(e) {
                if (e.keyCode === 13 || e.keyCode === 32) {
                    $(this).click();
                }
            });
        },


        featuredArticleList: function featuredArticleList() {
            var retryCount = 0;
            var MAX_RETRIES = 200; // 200 x 50ms = 10 seconds max wait

            function checkAndInit() {
                if ($('.featured-article-list .item').is(':visible')) {
                    _private.addCardCTA();
                } else if (retryCount < MAX_RETRIES) {
                    retryCount++;
                    setTimeout(checkAndInit, 50);
                }
            }

            checkAndInit();
        } // Truist Card List CTA button defect fixes ends here

