$(document).ready(function() {
    $('.cmp-truist-cards-list-v1').each(function() {
        var ids = $(this).find('.dynamic-cards').attr("id");
        window.CardView().init("#" + ids);
        var paginationType = $(this).find('.cardview-component').data('pagination-type');

        setTimeout(function() {
            if (paginationType === "pagination") {
                return;
            } else if (paginationType === "loadmore") {
                if ($('.newsgridcont').length > $('.cardview-component').attr('data-itemperpage')) {
                    $('.pg-show-more').removeClass('hide');
                } else {
                    $('.pg-show-more').addClass('hide');
                }
            }
        }, 1000);

    });
});
