$(document).ready(function() {
    $('.dynamic-cards .cards-filters-container').each(function() {
        var $filterContainer = $(this);
        var $selectWrappers = $filterContainer.find('.mdc-select');
        var $cardsFilterDropdowns = $selectWrappers.map(function() {
            return mdc.select.MDCSelect.attachTo(this)
        });
        $selectWrappers.each(function(index) {
            $cardsFilterDropdowns[index].listen('MDCSelect:change', function() {
                var applyButtonAnalyticsInfo = $cardsFilterDropdowns
                    .map(function() {
                        return $(this)[0].value
                    }).get()
                    .filter(function(val) {
                        return !/^-?$/.test(val)
                    })
                    .join(',');
                $filterContainer.find('.applyfilter')
                    .attr('data-wa-linkextrainfo', applyButtonAnalyticsInfo)
                    .attr('data-filter-value', applyButtonAnalyticsInfo);
            });
        });
        $filterContainer.find('.resetfilter').on('click keydown', function(ev) {
            if ((ev.type == 'click') || (ev.keyCode === 13) || (ev.keyCode === 32)) {
                $cardsFilterDropdowns.each(function() {
                    $(this)[0].selectedIndex = -1;
                });
            }
        });
    });

    setTimeout(function() {
        $('.cmp-cards-list .dynamic-cards').each(function() {

            if ($(this).hasClass('empty-cards-views')) {
                $(this).hide();
                $(this).closest('.horizontalTab').find('.r-tabs-nav li:last-child').hide();
            } else {
                $(this).show();
                $(this).closest('.horizontalTab').find('.r-tabs-nav li:last-child').show();
            }
        });
    }, 5000);

    setTimeout(function() {
        $('.cmp-truist-cards-list-v1 .dynamic-cards').each(function() {

            if ($(this).hasClass('empty-cards-views')) {
                $(this).hide();
                $(this).closest('.team-page-truist-tab').find('.js-ori-tabs__list li:last-child').hide();
            } else {
                $(this).show();
                $(this).closest('.team-page-truist-tab').find('.js-ori-tabs__list li:last-child').show();
            }
        });
    }, 4000);
});
